/* Notes photographs data. Kester Small. */
window.COURSE_NOTE_PHOTOS = {"M1U1":[{"screen":"Traditional media, digital media and digital art","src":"img/notes/n_l8cvrt3Hpec.jpg","w":1000,"h":667,"alt":"A white audio cassette tape on a plain surface","cap":"An audio cassette, a classic piece of traditional analogue media. Its sound was stored as magnetic patterns on tape, so every copy lost a little quality, unlike digital media stored as binary code.","by":"Daniel Schludi","title":"Real world:"},{"screen":"Core terminology","src":"img/notes/n_Y4zNMW3pQAs.jpg","w":1000,"h":668,"alt":"A man and a woman laughing together while looking at a smartphone outdoors","cap":"Two friends share a laugh over a smartphone. Moments like this show core terms in action: the phone is the device, the app is the platform, and what they watch is often user-generated content.","by":"Karthik Balakrishnan","title":"Real world:"},{"screen":"Technical terms: data, images and video","src":"img/notes/n_eVWWr6nmDf8.jpg","w":1000,"h":669,"alt":"Fibre optic cables plugged into a network switch in a server rack","cap":"Fibre optic cables connected to a network switch. Connections like these carry very high bandwidth, the amount of data per second, which makes broadband video and large file transfers possible.","by":"Kirill Sh","title":"Real world:"},{"screen":"Web, platform and rights terms","src":"img/notes/n_XFcAJqeZ75Q.jpg","w":1000,"h":750,"alt":"People scanning a QR code printed on a résumé with a smartphone","cap":"Someone scans a QR code on a résumé to open an online portfolio. The code simply holds a URL, linking a printed page to a web address where the work is hosted.","by":"Marielle Ursua","title":"Real world:"}],"M1U2":[{"screen":"From analogue to digital: a timeline","src":"img/notes/n_CbSIiGiK9sM.jpg","w":1000,"h":667,"alt":"A brown and black vintage radio on a wooden table","cap":"A vintage radio set. For much of the twentieth century, radio like this, alongside print and television, was how Caribbean households received news and music before the shift to digital.","by":"Maximilian Hofer","title":"Real world:"},{"screen":"Web 1.0 to Web 5.0","src":"img/notes/n_uiaNicmD2NM.jpg","w":1000,"h":668,"alt":"A waterfront resort with buildings beside the sea in St. Lucia","cap":"A resort in St. Lucia. A hotel like this shows the web's journey: a static brochure page in Web 1.0, guest reviews in Web 2.0, and personalised, smart services in later generations.","by":"Christina Victoria Craft","title":"Real world:"},{"screen":"Technologies, platforms and access","src":"img/notes/n_DmAKxLH0nhg.jpg","w":1000,"h":714,"alt":"A hand holding a smartphone photographing a building","cap":"A smartphone camera framing a building. Mobile devices, broadband and online platforms put capture, editing and publishing in one pocket, widening access to media creation.","by":"Thomas Russell","title":"Real world:"},{"screen":"Factors influencing future trends","src":"img/notes/n_5dFuO02OHh0.jpg","w":1000,"h":714,"alt":"A street vendor at a fruit stand holding a mobile phone","cap":"A street vendor at her fruit stand holds a mobile phone. Cost, usefulness and network coverage are factors that decide whether technologies such as mobile payments spread among small traders.","by":"Ali Mkumbwa","title":"Real world:"},{"screen":"Moving images: from optical toys to streaming","src":"img/notes/n_Lq6rcifGjOU.jpg","w":1000,"h":750,"alt":"Four reels of 8mm film lying on a white table","cap":"Reels of 8mm film. Moving images began with optical toys and film strips like these, then passed through cinema and television before arriving at digital files and streaming.","by":"Denise Jans","title":"Real world:"},{"screen":"Pre-cinema: the hunger for moving images","src":"img/notes/n_CHFJkF22ihg.jpg","w":1000,"h":667,"alt":"A retro metal spinning top toy on a wooden surface","cap":"A retro spinning top toy. Like the thaumatrope and zoetrope, spinning toys rely on persistence of vision: the eye blends quickly changing images, the principle behind all moving pictures.","by":"Anthony","title":"Real world:"},{"screen":"The birth of cinema and the silent era","src":"img/notes/n_-LxnF1Gr2t4.jpg","w":1000,"h":750,"alt":"Close-up of an old film projector","cap":"Close-up of an old movie projector. Machines like this threw light through moving film onto a screen, letting whole audiences share the silent films of early cinema.","by":"Richard Heinen","title":"Real world:"},{"screen":"Sound, colour and the studio system","src":"img/notes/n_OKLqGsCT8qs.jpg","w":1000,"h":563,"alt":"A vintage silver studio microphone","cap":"A vintage studio microphone. Recording equipment like this brought synchronised sound to film from 1927, changing acting, studios and how cinema was made.","by":"Matt Botsford","title":"Real world:"},{"screen":"Television's challenge, new waves and the blockbuster","src":"img/notes/n_U8kNV-0dCS0.jpg","w":1000,"h":751,"alt":"A grey vintage cathode-ray tube television in Romania","cap":"A vintage television set in Romania. As televisions entered homes from the 1950s, cinema lost audiences and answered with widescreen, colour and big-budget blockbusters.","by":"PJ Gal-Szabo","title":"Real world:"},{"screen":"Analogue to digital: cameras, editing, CGI and projection","src":"img/notes/n_yk9VXp4W5-Q.jpg","w":1000,"h":667,"alt":"A video editing timeline on a computer screen","cap":"A video editing timeline on screen. Non-linear digital editing replaced cutting celluloid by hand, letting editors rearrange shots instantly without damaging the original footage.","by":"Peter Stumpf","title":"Real world:"},{"screen":"Streaming, the platform era and Caribbean film","src":"img/notes/n_2Xq1-xOyDqk.jpg","w":1000,"h":563,"alt":"A father and son watching television together with popcorn at home","cap":"A father and son watch television at home with popcorn. Streaming platforms now bring films straight into living rooms, which also opens global audiences to Caribbean filmmakers.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"The analogue-to-digital timeline in depth","src":"img/notes/n_H9RkvByHP8U.jpg","w":1000,"h":667,"alt":"Several television antennas and satellite dishes on a weathered rooftop","cap":"TV aerials and satellite dishes on a rooftop. They mark the decades of broadcast and satellite television that came before broadband internet, streaming and on-demand media.","by":"Gio L","title":"Real world:"},{"screen":"Web 1.0: the read-only web","src":"img/notes/n_aiqKc07b5PA.jpg","w":1000,"h":631,"alt":"An old cathode-ray tube computer monitor, switched off","cap":"An old CRT computer monitor. Screens like this displayed the Web 1.0 read-only web of static pages, where a few webmasters published and everyone else simply read.","by":"Federica Galli","title":"Real world:"},{"screen":"Web 2.0: the social, read-write web","src":"img/notes/n_EvDye05TZMw.jpg","w":1000,"h":563,"alt":"Four friends laughing at a smartphone in a sunlit café","cap":"Friends laugh together over a phone in a café while sharing photos. This is Web 2.0: the read-write, social web where users create, comment on and share content themselves.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Web 3.0: the semantic, intelligent web","src":"img/notes/n_fEsi8nn6a1g.jpg","w":1000,"h":667,"alt":"A smartphone screen showing an assistant interface","cap":"A smartphone showing an assistant interface. Web 3.0 services use machine-readable data and AI to understand requests and personalise results for each user.","by":"Zulfugar Karimov","title":"Real world:"},{"screen":"Web 4.0: the symbiotic web (emerging)","src":"img/notes/n_3_nf1qKJGf4.jpg","w":1000,"h":667,"alt":"A finger adjusting a modern digital thermostat on a wall","cap":"A finger adjusts a digital thermostat. Connected devices like this belong to the Internet of Things, the network of sensors and controls that Web 4.0 links with AI and real-time data.","by":"HUUM","title":"Real world:"},{"screen":"Web 5.0: the sensory and emotional web (speculative)","src":"img/notes/n_f0BJ6TXXtuM.jpg","w":1000,"h":563,"alt":"A young woman wearing a VR headset reaching out with her hands","cap":"A young woman reaches out while wearing a VR headset. Immersive, sensory experiences like this hint at the speculative Web 5.0, where systems may respond to emotions and senses.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Enabling technologies: broadband, mobile, data and AI","src":"img/notes/n_8oR7XykOjk4.jpg","w":1000,"h":667,"alt":"Yellow and green fibre optic cables for fibre-to-the-home","cap":"Fibre-to-the-home cables. Broadband connections like these were a key enabler, making streaming, video calls and cloud services practical for homes and businesses.","by":"Ronald Crow","title":"Real world:"},{"screen":"Accessibility and connectivity: enablers versus barriers","src":"img/notes/n_pjW5WezrdJk.jpg","w":1000,"h":563,"alt":"A technician on a lift working on a mobile phone tower","cap":"A technician works on a mobile phone tower. Network coverage is the first requirement for access; where masts are missing, the cost of devices and data becomes a barrier on top of poor signal.","by":"iStrfry , Marcus","title":"Real world:"},{"screen":"Comparing Web 1.0 to Web 5.0","src":"img/notes/n_SsDZRqcCfSo.jpg","w":1000,"h":667,"alt":"A row of old desktop computers on a desk","cap":"A row of old desktop computers. Comparing them with today's phones, smart homes and headsets helps show how each Web generation changed interaction, devices and content.","by":"Mert Kahveci","title":"Real world:"}],"M1U3":[{"screen":"Digital art, audio and animation","src":"img/notes/n_CGpifH3FjOA.jpg","w":1000,"h":667,"alt":"A designer using a drawing tablet and laptop with colour swatches and markers","cap":"A designer works with a drawing tablet, laptop, colour swatches and markers. Digital art and illustration combine traditional design skills with digital tools and software.","by":"Theme Photos","title":"Real world:"},{"screen":"Apps, devices, photography, video, publishing and more","src":"img/notes/n_-BjfPsoziRU.jpg","w":1000,"h":583,"alt":"Behind the scenes of a promotional video shoot with a camera on a stabiliser","cap":"Behind the scenes of a promotional video shoot with a professional camera rig. Digital video sits alongside apps, photography and publishing as a major type of digital media.","by":"TopSphere Media","title":"Real world:"},{"screen":"Digital media tools","src":"img/notes/n_ZDNyhmgkZlQ.jpg","w":1000,"h":667,"alt":"A home podcasting setup with a microphone and a desktop computer","cap":"A home podcast setup with a microphone and recording software on a desktop. Affordable digital media tools like these let one person record, edit and publish audio.","by":"Will Francis","title":"Real world:"},{"screen":"Workflow activities","src":"img/notes/n_xzzgY__zX8A.jpg","w":1000,"h":667,"alt":"Hand-drawn website layout sketches on paper","cap":"Hand-drawn website layout sketches. Planning and wireframing on paper is an early workflow activity, coming before production, testing and publishing to an audience.","by":"Hal Gatewood","title":"Real world:"},{"screen":"What is digital media? Analogue versus digital","src":"img/notes/n_GTIutdltrkA.jpg","w":1000,"h":763,"alt":"A vinyl record spinning on a turntable","cap":"A vinyl record playing on a turntable. Its grooves are a continuous analogue copy of sound waves, while a digital track stores the same music as binary numbers.","by":"Andrea Cipriani","title":"Real world:"},{"screen":"Four questions for classifying any media product","src":"img/notes/n_78z3qaiYN8I.jpg","w":1000,"h":664,"alt":"A carnival masquerader in a purple feathered costume in Port of Spain, Trinidad","cap":"A masquerader in a purple feathered costume at Carnival in Port of Spain, Trinidad. Media about a festival like this can be classified by its purpose, features and production requirements.","by":"Holger Woizick","title":"Real world:"},{"screen":"Nine major types (1): digital art, digital audio, animation","src":"img/notes/n_Hg3BHX6U5jg.jpg","w":1000,"h":660,"alt":"Two men wearing headphones recording a podcast at a wooden table","cap":"Two people record a podcast with microphones and headphones. Podcasting is digital audio: its purpose is to inform or entertain, and it needs recording and editing equipment to produce.","by":"Austin Distel","title":"Real world:"},{"screen":"Nine major types (2): apps and games, devices, photography","src":"img/notes/n_7Y-80zveMRM.jpg","w":1000,"h":667,"alt":"A woman photographing pink flowers with her smartphone","cap":"A woman photographs pink mountain laurel flowers with her phone. Smartphones blur the line between devices and photography, putting a capable camera in most people's hands.","by":"Audri Van Gores","title":"Real world:"},{"screen":"Nine major types (3): social, data design, immersive","src":"img/notes/n_IMUwe-p1yqs.jpg","w":1000,"h":750,"alt":"Four people trying out virtual reality goggles together","cap":"Four people try out virtual reality goggles. Immersive media like VR places users inside a scene, and producing it needs 3D content, specialist software and suitable headsets.","by":"Lucrezia Carnelos","title":"Real world:"},{"screen":"The nine types at a glance, and command words","src":"img/notes/n_omeaHbEFlN4.jpg","w":1000,"h":667,"alt":"Two students reading books and writing notes at a wooden picnic table","cap":"Students revise together with books and notebooks. Summarising the nine media types and practising command words such as describe, explain and evaluate prepares you for exam answers.","by":"Alexis Brown","title":"Real world:"},{"screen":"Information visualisation: choosing the right chart","src":"img/notes/n_yqaskj8lQBE.jpg","w":1000,"h":667,"alt":"A screen showing a bar chart on an analytics dashboard","cap":"An analytics dashboard showing a bar chart. Bar charts are the right choice for comparing categories, while lines suit change over time and other chart types answer other questions.","by":"1981 Digital","title":"Real world:"},{"screen":"Honest data design: scales, data-ink and labels","src":"img/notes/n_Wb63zqJ5gnE.jpg","w":1000,"h":664,"alt":"Stock market charts displayed on a monitor during live trading","cap":"Stock charts on a trading monitor. Small price moves can look dramatic when the axis is truncated, which is why honest data design checks scales, baselines and labels.","by":"Nicholas Cappello","title":"Real world:"},{"screen":"Infographics and interactive data stories","src":"img/notes/n_xZgvBXDB9wE.jpg","w":1000,"h":750,"alt":"Hand-drawn charts and diagrams on a whiteboard","cap":"Charts sketched on a whiteboard. Infographic designers often plan the story first, choosing which charts and words will guide the audience through the information step by step.","by":"Amélie Mourichon","title":"Real world:"}],"M1U4":[{"screen":"How organisations use digital media","src":"img/notes/n_KdMgzo4Okb8.jpg","w":1000,"h":563,"alt":"A clothing designer photographing garments with a smartphone","cap":"A clothing designer photographs garments with a smartphone for social media. Small businesses use digital media like this to market products, reach customers and sell online.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"The technology adoption lifecycle","src":"img/notes/n_cHbyGVOQspk.jpg","w":1000,"h":563,"alt":"An elderly woman smiling at a smartphone on a sofa","cap":"An older woman enjoys content on her smartphone. In the adoption lifecycle, late majority users and laggards take up a technology only once it is familiar, simple and clearly useful.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Industries, benefits, limitations and disruption","src":"img/notes/n_rMaWin9-9Gk.jpg","w":1000,"h":602,"alt":"Aerial view of cruise ships docked in the Bahamas","cap":"Cruise ships docked in the Bahamas. Tourism is an industry transformed by digital media, from online booking and reviews to social media marketing, bringing both benefits and disruption.","by":"Fernando Jorge","title":"Real world:"},{"screen":"Careers and work models","src":"img/notes/n_-X4Qx4_4iMU.jpg","w":1000,"h":563,"alt":"A group of students waving at a video call on a laptop","cap":"Students wave during a video conference on a laptop. Video calls like this support remote and hybrid work models, letting digital media professionals collaborate from anywhere.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"The adoption curve: five groups, reasons and barriers","src":"img/notes/n_Rv44KdOiOPQ.jpg","w":1000,"h":667,"alt":"People leaning over a table to examine several new smartphones on display","cap":"People try out new smartphones laid out on a display table. Those keen to handle a device first are like the innovators and early adopters on the curve; most people wait until the benefits are proven.","by":"appshunter.io","title":"Real world:"},{"screen":"Characteristics of successful adopters","src":"img/notes/n_jMsJlnMMyZI.jpg","w":1000,"h":667,"alt":"Woman filming a bakery display case with a smartphone","cap":"A woman films a bakery display on her phone. Successful adopters plan content like this deliberately, posting consistent, appealing visuals that match their audience and goals, such as building online pre-orders.","by":"Jenna Day","title":"Real world:"},{"screen":"Benefits and limitations across sectors","src":"img/notes/n_OhTbOJH4w-w.jpg","w":1000,"h":800,"alt":"Young man working at a computer in a dimly lit home music studio","cap":"A young music producer works in a home studio at night. Cheaper tools let musicians produce from home and reach fans directly, one benefit of digital media in music, though streaming pays very little per play.","by":"Rezli","title":"Real world:"},{"screen":"Digital media career pathways","src":"img/notes/n_VW2oU66mwbc.jpg","w":1000,"h":506,"alt":"Person in silhouette wearing headphones, editing video on a computer in a dark room","cap":"An editor wearing headphones works through footage on a computer. Video editor is one of the core digital media pathways: cutting, sequencing, colour-correcting and exporting footage.","by":"Mark Cruz","title":"Real world:"},{"screen":"Modern work models and why they matter here","src":"img/notes/n_fRGoTJFQAHM.jpg","w":1000,"h":748,"alt":"Laptop showing a video conference with many participants beside a coffee mug","cap":"A laptop shows a video meeting with many colleagues. Remote work and cloud collaboration rely on calls like this, letting a Caribbean creator serve distant clients, provided the internet connection is reliable.","by":"Compare Fibre","title":"Real world:"},{"screen":"Disruption: when industries fail to adapt","src":"img/notes/n_HqA7l8IbhmY.jpg","w":1000,"h":667,"alt":"Rows of old VHS video tapes lined up on a shelf","cap":"Rows of VHS tapes sit on a shelf. Video rental shops built on physical tapes declined as streaming and on-demand viewing grew, a clear example of disruption when an industry fails to adapt.","by":"Delaney Van","title":"Real world:"}],"M1U5":[{"screen":"What is the Open Movement?","src":"img/notes/n_B4p46KlvkXs.jpg","w":1000,"h":563,"alt":"Small street-side free library box filled with books","cap":"A little free library offers books to anyone passing by. It captures the Open Movement idea that knowledge and creative works should be freely available for people to use and share.","by":"Nihar Bhagat","title":"Real world:"},{"screen":"Creative Commons licensing","src":"img/notes/n_DQPP9rVLYGQ.jpg","w":1000,"h":677,"alt":"Man looking through a DSLR camera viewfinder","cap":"A photographer takes a picture. The image is automatically his copyright, but with a Creative Commons licence he could give everyone permission in advance to reuse it, as long as they credit him (BY).","by":"Jakob Owens","title":"Real world:"},{"screen":"Open source, public domain, fair dealing and CC compared","src":"img/notes/n_RoDSZoVzBVs.jpg","w":1000,"h":587,"alt":"Antique hand-drawn world map showing continents and oceans","cap":"This world map from 1736 is held by a public library. Copyright on works this old has long expired, so it is in the public domain: anyone may use it without permission, though credit is good practice.","by":"The New York Public Library","title":"Real world:"},{"screen":"The Open Movement: an umbrella of open ideas","src":"img/notes/n_ourQHRTE2IM.jpg","w":1000,"h":667,"alt":"Man in glasses typing on a laptop in a dimly lit workspace at a hackathon","cap":"A participant codes at a hackathon. Events like this bring people together to build and share freely, reflecting the umbrella of open ideas: open source, open data and open knowledge.","by":"Alex Kotliarskyi","title":"Real world:"},{"screen":"Open source: read it, modify it, share it","src":"img/notes/n_4hbJ-eymZ1o.jpg","w":1000,"h":667,"alt":"Lines of colourful HTML code on a dark screen","cap":"Lines of source code fill a screen. In open source software this human-readable code is published, so anyone can read it, fix it, improve it and share it under licences such as GPL or MIT.","by":"Florian Olivo","title":"Real world:"},{"screen":"Open data: types, definition and the knowledge pyramid","src":"img/notes/n_5477L9Z5eqI.jpg","w":1000,"h":666,"alt":"A hurricane seen from space, with swirling clouds over the ocean","cap":"A hurricane photographed from space. Weather and storm-tracking data like this, when openly published in machine-readable formats, helps Caribbean agencies and communities prepare, turning raw data into useful knowledge.","by":"NASA","title":"Real world:"},{"screen":"What makes data open, and why we need it","src":"img/notes/n_hpjSkU2UYSU.jpg","w":1000,"h":713,"alt":"Laptop screen showing charts and statistics","cap":"Statistics and charts on a laptop screen. Data like this is only truly open if the whole dataset is accessible, freely reusable and redistributable, even commercially, with no limits on who may use it.","by":"Carlos Muza","title":"Real world:"},{"screen":"Open access, OER and the 5 Rs","src":"img/notes/n_kp7qkHTgSKc.jpg","w":1000,"h":563,"alt":"Group of students gathered around a laptop in a university lecture hall","cap":"Students study together around a laptop. Open access research and open educational resources let learners like these read, download, share and reuse materials freely, retaining, revising and remixing them for their own needs.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Intellectual property and the array of rights","src":"img/notes/n_d74abIkBrrw.jpg","w":1000,"h":750,"alt":"Antique experimental telephone receiver mounted on a wooden base","cap":"An experimental telephone from 1876, linked to a United States patent. Patents protect inventions as industrial property, one of the two main categories of intellectual property alongside copyright.","by":"Smithsonian","title":"Real world:"},{"screen":"Four terms students confuse","src":"img/notes/n_7sPg5OLfExc.jpg","w":1000,"h":667,"alt":"Pile of old photographs in a brown wooden chest","cap":"A chest of old photographs. Whether you may reuse one depends on its status: public domain, Creative Commons, fair dealing or still fully protected. Students often confuse these four terms.","by":"Roman Kraft","title":"Real world:"},{"screen":"Benefits and responsibilities of open content","src":"img/notes/n_rrKC89GTI9I.jpg","w":1000,"h":667,"alt":"Second-hand books spread out for sale on a green surface at an outdoor market","cap":"Second-hand books are laid out for sale. Selling is commercial use, so anyone selling work built on open content must check the licence: a NonCommercial (NC) licence forbids it.","by":"Amir M. Mohamadi","title":"Real world:"}],"M1U6":[{"screen":"Why Caribbean-centric content matters","src":"img/notes/n_PIquPw1YDQk.jpg","w":1000,"h":664,"alt":"Woman in an elaborate purple and gold carnival costume","cap":"A masquerader in a purple and gold costume, captioned 'Trini to the bone' by the photographer. Carnival costume, music and heritage are exactly the kind of Caribbean identity that Caribbean-centric content puts on screen.","by":"Holger Woizick","title":"Real world:"},{"screen":"Barriers and benefits in the Caribbean","src":"img/notes/n_57Cx3I3DXN8.jpg","w":1000,"h":753,"alt":"Leaning utility pole and power lines over a flooded landscape under storm clouds","cap":"A utility pole leans over floodwater beneath storm clouds. Damaged power and network infrastructure from storms and hurricanes is one barrier that has slowed digital media development in the Caribbean.","by":"Maksudur Rahman Rahat","title":"Real world:"},{"screen":"What is a digital media platform?","src":"img/notes/n_-NWGWmcEwi4.jpg","w":1000,"h":667,"alt":"Satellite dish mounted on a building wall","cap":"A satellite dish on a building wall. Satellite is one of the networks, alongside cable, telco, terrestrial broadcasting and the Internet, through which digital media platforms deliver video, audio and data.","by":"Rasta Gubaz","title":"Real world:"},{"screen":"Choosing the right platform","src":"img/notes/n_Zk3sXhNbqJM.jpg","w":1000,"h":563,"alt":"Smartphone on a small tripod filming a sunset over the sea","cap":"A phone on a mini tripod films a sunset. Before shooting, a creator should check the platform's file specifications, such as 9:16 for reels or 16:9 for widescreen video.","by":"Mark de Jong","title":"Real world:"},{"screen":"Caribbean-centred content: our voice, our needs, our reach","src":"img/notes/n_98t43MWNJdQ.jpg","w":1000,"h":828,"alt":"Group of people in carnival costumes standing together on a street","cap":"Masqueraders at Carnival 2024 in Trinidad and Tobago. When Caribbean people photograph and share their own celebrations, they tell their own stories in their own voice rather than being described by others.","by":"Anton Acosta","title":"Real world:"},{"screen":"Meeting local needs and what digital media can do for the region","src":"img/notes/n_SmonWKkWDbw.jpg","w":1000,"h":667,"alt":"Roadside fruit stand with a sign advertising cold coconuts","cap":"A roadside stand sells cold coconuts. Small vendors like this can grow with simple branding, a social media page or an online shop, showing how digital media meets local business needs.","by":"Zevon Jackson","title":"Real world:"},{"screen":"Where open meets Caribbean, and representing culture ethically","src":"img/notes/n_tyB4VfStCQI.jpg","w":1000,"h":751,"alt":"Man sitting at a table with scissors in a community yard","cap":"A man at Life Yard community in downtown Kingston, Jamaica. Representing community life ethically means gaining consent, crediting people and avoiding stereotypes when filming or photographing them.","by":"Nigel SB Photography","title":"Real world:"},{"screen":"Digital media platforms: definition and types","src":"img/notes/n_yubCnXAA3H8.jpg","w":1000,"h":667,"alt":"Person resting feet on a table while watching television in a living room","cap":"A person relaxes watching television at home. A streaming service is a digital media platform because it delivers video over the Internet; the television itself is only the device.","by":"Mollie Sivaram","title":"Real world:"},{"screen":"What each platform does","src":"img/notes/n_4GyrlS5-PGM.jpg","w":1000,"h":667,"alt":"A man and a woman wearing headsets and looking at a laptop while recording","cap":"Two people record a podcast together. Podcasts are used for interviews, storytelling and teaching, and episodes are shared through an RSS feed that podcast apps pick up.","by":"Flipsnack","title":"Real world:"},{"screen":"Platform considerations and Caribbean market access","src":"img/notes/n_YzZJUXjb9aw.jpg","w":1000,"h":563,"alt":"Tall metal telecommunications tower against a blue sky","cap":"A telecommunications tower carries mobile signals. Caribbean market access depends on coverage and data costs like this, so creators should compress files and design content that works on slower connections.","by":"Kabiur Rahman Riyad","title":"Real world:"}],"M1U7":[{"screen":"Opportunities of digital media and the Internet","src":"img/notes/n_5MUw_NHo5i4.jpg","w":1000,"h":667,"alt":"Person filming a woman playing guitar with a camera","cap":"A camera operator films a guitarist. Recording and sharing performances online is one opportunity of digital media, supporting creativity, collaboration and content sharing with audiences worldwide.","by":"Kyle Loftus","title":"Real world:"},{"screen":"Pitfalls, risks and responsibilities","src":"img/notes/n_FPt10LXK0cg.jpg","w":1000,"h":667,"alt":"Row of hands holding smartphones while people wait","cap":"A row of people scroll their phones while waiting for a delayed train. Constant scrolling shows pitfalls such as time-consuming use and growing digital footprints that may be found later.","by":"ROBIN WORRALL","title":"Real world:"},{"screen":"AI in digital media: benefits and industry expectations","src":"img/notes/n_CjWsslYVnPI.jpg","w":1000,"h":752,"alt":"Side view of a white humanoid robot face on a black background","cap":"A humanoid robot's face in profile. Artificial intelligence performs tasks that normally need human intelligence; in digital media it helps with captions, translation, analytics and repetitive editing tasks.","by":"Gabriele Malaspina","title":"Real world:"},{"screen":"AI risks and ethical implications","src":"img/notes/n_JjGXjESMxOY.jpg","w":1000,"h":884,"alt":"White humanoid robot with a visible mechanical face","cap":"A white humanoid robot. Machines can imitate humans convincingly, which is why AI risks such as deepfakes, hallucinated facts and bias call for careful, critical and ethical use.","by":"Franck V.","title":"Real world:"},{"screen":"Digital media cuts both ways","src":"img/notes/n_qZenO_gQ7QA.jpg","w":1000,"h":667,"alt":"People standing outdoors at night looking at their phones","cap":"People stand checking their phones. The same devices connect, inform and entertain them yet also expose them to misinformation and privacy risks: digital media cuts both ways.","by":"camilo jimenez","title":"Real world:"},{"screen":"Pitfalls (1): harmful intent, footprint, manipulation and inequality","src":"img/notes/n_mT7lXZPjk7U.jpg","w":1000,"h":667,"alt":"Red padlock resting on a black computer keyboard","cap":"A padlock rests on a keyboard. It is a reminder of data exposure: card numbers and health records can reach the wrong hands through breaches, phishing and insecure platforms.","by":"FlyD","title":"Real world:"},{"screen":"Pitfalls (2): social harm, health and misread messages","src":"img/notes/n_FLdK5N-YGf4.jpg","w":1000,"h":668,"alt":"Young person sitting alone on concrete stairs","cap":"A young person sits alone on a stairway. Cyberbullying, harassment and doxxing can leave victims feeling isolated, so online harms affect real-world health and wellbeing.","by":"Gaelle Marcel","title":"Real world:"},{"screen":"Weighing opportunities against pitfalls","src":"img/notes/n_98MbUldcDJY.jpg","w":1000,"h":667,"alt":"Brown and beige balance weighing scale","cap":"A balance scale weighs two sides. Before posting, weigh the opportunities of digital media against its pitfalls, asking who benefits, who is harmed and who is left out.","by":"Piret Ilver","title":"Real world:"}],"M1U8":[{"screen":"What is intellectual property?","src":"img/notes/n_e7mLjYK3odM.jpg","w":1000,"h":758,"alt":"Antique clockwork baby doll with an old patent office tag attached","cap":"An 1871 patent model of a mechanical crawling doll, still tagged by the patent office. Inventions like this are protected by patents, one type of intellectual property alongside copyright and trademarks.","by":"Smithsonian","title":"Real world:"},{"screen":"Protecting your work: process and legislation","src":"img/notes/n_9XK7vgoGSgc.jpg","w":1000,"h":667,"alt":"Woman taking a photograph with a black camera outdoors","cap":"A woman takes a photograph outdoors. Copyright arises automatically once her image is saved; keeping original files and adding a copyright notice and metadata helps prove she owns it.","by":"Erik Mclean","title":"Real world:"},{"screen":"Authorised use, user agreements and infringement","src":"img/notes/n_lrgF9FSQeKc.jpg","w":1000,"h":654,"alt":"Woman reclining on a beach chair in the shade with ocean and an island beyond","cap":"A woman relaxes on a beach chair with Han Lollick island on the horizon. A hotel might license a photo like this as royalty-free stock or under a rights-managed agreement.","by":"Karl Callwood","title":"Real world:"},{"screen":"Ethical issues and human rights online","src":"img/notes/n_zAhAUSdRLJ8.jpg","w":1000,"h":667,"alt":"Open padlock surrounded by scattered keyboard keys under red and green light","cap":"An open padlock among scattered keyboard keys. Cracked or pirated software can leave systems open like this to malware and ransomware, which is why free, open-source alternatives are the ethical choice.","by":"FlyD","title":"Real world:"},{"screen":"Governance frameworks, responsible practice and consequences","src":"img/notes/n_mIalf1tw6-w.jpg","w":1000,"h":703,"alt":"Many national flags flying from poles against a blue sky","cap":"Flags of many nations fly together. International frameworks such as the UDHR, UNESCO guidance and WIPO treaties set shared rules for rights, privacy and intellectual property online.","by":"Saj Shafique","title":"Real world:"},{"screen":"Meet the team: what could go wrong?","src":"img/notes/n_Hn3S90f6aak.jpg","w":1000,"h":667,"alt":"Person holding a clapperboard on a film set","cap":"A clapperboard marks a take on a film set. Every student production must clear the rights to music, clips and images it uses, and get consent from the people it films.","by":"Avel Chuklanov","title":"Real world:"}],"M2U1":[{"screen":"Who is the digital user?","src":"img/notes/n_gOgETQMNNgY.jpg","w":1000,"h":563,"alt":"A young girl and her grandmother taking a selfie with a smartphone at a kitchen table","cap":"A girl takes a selfie with her grandmother. The child, raised with smartphones, fits the idea of a digital native; her grandmother, who learned these tools later in life, fits the digital immigrant.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Beliefs, attitudes and practices","src":"img/notes/n_GU3BNpkdQlA.jpg","w":1000,"h":667,"alt":"An older man wearing glasses reading a printed newspaper","cap":"An older man reads a printed newspaper. This reflects a typical digital immigrant belief that reliable information comes from established sources such as newspapers, in contrast with digital natives who expect news to be instant, free and on their phones.","by":"Çağlar Oskay","title":"Real world:"},{"screen":"Rights and needs of the digital generation","src":"img/notes/n_zniM2Qqaxv4.jpg","w":1000,"h":667,"alt":"A child's hands typing on a laptop keyboard, seen from above","cap":"A child's hands on a laptop keyboard, trying to log in. Every time a young person goes online, their rights to privacy, access to information and protection from harm must apply just as they do offline.","by":"Vlad Deep","title":"Real world:"},{"screen":"Personas, segments and prosumers","src":"img/notes/n_w00FkE6e8zE.jpg","w":1000,"h":667,"alt":"A team arranging sticky notes on a wall during a planning session","cap":"A design team maps a user journey with sticky notes. Professionals use sessions like this to group audiences into segments and build user personas, so every design decision is made for a believable person with real goals and frustrations.","by":"UX Indonesia","title":"Real world:"},{"screen":"Natives and immigrants side by side","src":"img/notes/n_QJVk5Wzl6s8.jpg","w":1000,"h":563,"alt":"A grandfather and young grandson sitting on a sofa looking at a tablet together","cap":"A grandfather and grandson share a tablet. The boy has never known life without touchscreens, a digital native, while his grandfather adopted the technology later in life, a digital immigrant adapting older habits to a new device.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Four rights and needs","src":"img/notes/n_CPAcOKMZGiw.jpg","w":1000,"h":666,"alt":"A young girl wearing glasses sitting in front of a laptop screen","cap":"A young girl works at a laptop. Her online life depends on all four needs in the notes: access to a device and internet, privacy for her data, literacy to judge what she sees, and safety from harassment and misinformation.","by":"UK Black Tech","title":"Real world:"},{"screen":"What makes a digital native","src":"img/notes/n_IIsItGCqSPY.jpg","w":1000,"h":670,"alt":"Two teenagers standing side by side, each holding a smartphone","cap":"Two teenagers stand together, each on their own phone. Digital natives like these move easily between apps and platforms, multitask and communicate through many digital channels at once, often while also in the same physical space.","by":"yep nope","title":"Real world:"},{"screen":"Generations of digital natives","src":"img/notes/n_tQPgM1k6EbQ.jpg","w":1000,"h":514,"alt":"A small boy sitting at a table using a tablet computer","cap":"A young boy learns the alphabet on a tablet. Children like him belong to Generation Alpha, growing up with tablets and smart devices from early childhood, a step beyond Millennials, who watched the internet arrive.","by":"Kelly Sikkema","title":"Real world:"},{"screen":"Digital immigrants and a symbiotic relationship","src":"img/notes/n_UWZNnNQjraI.jpg","w":1000,"h":667,"alt":"An older man and woman sitting on a sofa looking at a tablet together","cap":"Two older adults explore a tablet together. Digital immigrants face a learning curve, but they bring patience, care for quality and life experience, which younger users can learn from in a symbiotic relationship.","by":"Centre for Ageing Better","title":"Real world:"}],"M2U2":[{"screen":"Defining the digital media ecosystem","src":"img/notes/n_UqqlvOaj6ZE.jpg","w":1000,"h":750,"alt":"A colourful parrotfish swimming over a coral reef","cap":"A parrotfish swims over a coral reef, where fish, coral and water all depend on one another. The digital media ecosystem works the same way: creators, platforms, networks, audiences and regulators each rely on the others to survive.","by":"Nuraini Arsad","title":"Real world:"},{"screen":"The elements of the ecosystem","src":"img/notes/n_ntqaFfrDdEA.jpg","w":1000,"h":667,"alt":"A small film crew standing around a camera set up on location","cap":"A crew gathers around a camera on a shoot. A single production like this brings together several ecosystem elements: creators with the idea, producers organising the shoot, skilled professionals running the gear, and a client or audience it is made for.","by":"Jakob Owens","title":"Real world:"},{"screen":"Types of media, major players and infrastructure","src":"img/notes/n_ryRU-cd1yas.jpg","w":1000,"h":563,"alt":"A group of young people playing games on computers in a dark room","cap":"A group plays online games side by side. Gaming is one of the main types of media in the ecosystem, alongside reading, audio, video, social and mobile, and it relies on fast networks and servers to connect players.","by":"Stem List","title":"Real world:"},{"screen":"Emerging trends","src":"img/notes/n_8vn4KvfU640.jpg","w":1000,"h":693,"alt":"A woman holding a white virtual reality headset","cap":"A woman holds a virtual reality headset. Augmented and virtual reality is one of the emerging trends in digital media, making possible immersive experiences such as a virtual tour of a heritage site.","by":"Maxim Hopman","title":"Real world:"},{"screen":"The ecosystem at a glance","src":"img/notes/n_yhJVLxcquEY.jpg","w":1000,"h":714,"alt":"Rows of yellow and green fibre optic cables neatly plugged into a panel","cap":"Fibre optic cables neatly connected in a network panel. This hidden infrastructure links every part of the digital media ecosystem, so a fault in one place can ripple across creators, platforms and audiences everywhere.","by":"Albert Stoynov","title":"Real world:"},{"screen":"The twelve key elements","src":"img/notes/n_DxpbViLoSmo.jpg","w":1000,"h":562,"alt":"A smartphone mounted in front of a circular ring light","cap":"A phone set up in front of a ring light, the typical kit of an independent creator. Creators are one of the twelve key elements, generating original content often through social platforms.","by":"Наталья Емашова","title":"Real world:"},{"screen":"Three emerging trends","src":"img/notes/n_qa2IMwBGP1E.jpg","w":1000,"h":667,"alt":"A ring light with a smartphone mounted in the centre","cap":"A phone mounted in a ring light, ready to film short clips. This simple set-up is the tool of short-form vertical video and the creator economy, two trends that let independent creators build audiences from home.","by":"Solen Feyissa","title":"Real world:"}],"M2U3":[{"screen":"What is a value chain?","src":"img/notes/n_1-ZUhMFleK0.jpg","w":1000,"h":663,"alt":"A worker picking ripe coffee berries from bushes on a small mountain plantation","cap":"A worker picks coffee berries on a small plantation in Taiwan. The berries pass through many hands before becoming a cup of coffee, just as a media product gains value at each link of a value chain.","by":"Luba Glazunova","title":"Real world:"},{"screen":"Stakeholders from producer to end-user","src":"img/notes/n_mP9BG1m9t5M.jpg","w":1000,"h":563,"alt":"A film crew and equipment gathered outside a building on a city street","cap":"A crew films a TV drama on location. Producers, camera operators and sound crew are stakeholders at the production stage; distributors, marketers and audiences follow further along the chain.","by":"Jim Thring","title":"Real world:"},{"screen":"The impact of digital media on the value chain","src":"img/notes/n_wkHTVxBNBrY.jpg","w":1000,"h":667,"alt":"A home recording studio filled with keyboards, speakers and music equipment","cap":"A home recording studio packed with affordable equipment. Digital tools let artists record, release and promote from home, cutting out steps that once needed a record label and pressing plant.","by":"Clay Banks","title":"Real world:"},{"screen":"Interdependencies and Caribbean value creation","src":"img/notes/n__-PY-2WQl10.jpg","w":1000,"h":748,"alt":"A mobile phone tower with antennas against a blue sky","cap":"A mobile phone mast carries the signal that content needs to travel. Infrastructure is the link every player depends on: if storm damage takes towers down, creators, platforms and audiences are all cut off.","by":"Dena Skulskaya","title":"Real world:"},{"screen":"Four key aspects of the value chain","src":"img/notes/n_CbNBjnXXhNg.jpg","w":1000,"h":667,"alt":"Rows of vinyl records displayed in bins in a record shop","cap":"Vinyl records lined up in a shop's jazz section. A record passes through creation, production, distribution and consumption, the key aspects of a value chain.","by":"Mick Haupt","title":"Real world:"},{"screen":"Five stakeholders","src":"img/notes/n_Dnkr_lmdKi8.jpg","w":1000,"h":667,"alt":"A blank outdoor billboard on tall supports against the sky","cap":"A blank billboard waiting for an advertisement. Advertisers and marketers are one of the stakeholders in the value chain, paying to reach the audiences that creators attract.","by":"Kate Trysh","title":"Real world:"},{"screen":"Before and after digital","src":"img/notes/n_Qnlp3FCO2vc.jpg","w":1000,"h":667,"alt":"A crowd raising their hands and cheering at a live concert","cap":"A crowd cheers at a live concert. Before digital, fans mostly paid for records and tickets; now the same audience streams, shares and films the show, changing how value flows.","by":"Tijs van Leur","title":"Real world:"},{"screen":"Interdependencies","src":"img/notes/n_dC2fbPZ8Oec.jpg","w":1000,"h":563,"alt":"A fallen tree and downed power lines blocking a road beside a parked car","cap":"A tree brought down by Hurricane Milton blocks a road and damages power lines in Tampa, Florida. When power fails, so do networks and platforms, showing how every link in the chain depends on the others.","by":"Erok Mule","title":"Real world:"}],"M2U4":[{"screen":"Globalisation and the pace of change","src":"img/notes/n_Annl9CjEaEs.jpg","w":1000,"h":666,"alt":"Stacks of shipping containers at a busy port harbour","cap":"Shipping containers stacked at Dar es Salaam port. Goods move around the world quickly, and digital media moves even faster, which is why globalisation speeds up the pace of change in the industry.","by":"Ali Mkumbwa","title":"Real world:"},{"screen":"Work models","src":"img/notes/n_62Im7nCqpmY.jpg","w":1000,"h":750,"alt":"Two adults sitting at a table on the wooden deck of a beach cabin","cap":"Two people sit at a table on a beach cabin deck. With a laptop and a connection, work can happen far from an office, the idea behind remote and flexible work models.","by":"Rein Krijgsman","title":"Real world:"},{"screen":"The modern digital media workplace","src":"img/notes/n_X_HYpBaEgtA.jpg","w":1000,"h":563,"alt":"Colleagues in a meeting room watching a man on a computer screen during a video call","cap":"Colleagues in an office talk with a teammate on a video call. The modern digital media workplace mixes people in the room with people online.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Skills for employment and entrepreneurship","src":"img/notes/n_s9CC2SKySJM.jpg","w":1000,"h":667,"alt":"A designer sketching website wireframes on paper beside a mug","cap":"A designer sketches wireframes by hand before building anything on screen. Planning, design and problem solving are skills employers and clients expect.","by":"Unseen Studio","title":"Real world:"},{"screen":"Dispositions: the habits behind the skills","src":"img/notes/n_dhGFLj3rI0Q.jpg","w":1000,"h":667,"alt":"A rowing crew pulling together through choppy sea during a regatta","cap":"A rowing crew battles rough seas in a regatta at Málaga after a storm blew in. Teamwork, resilience and persistence are the dispositions that make skills useful when conditions get hard.","by":"Quino Al","title":"Real world:"},{"screen":"Remote, hybrid and flexible work","src":"img/notes/n_a8coCLg6O-U.jpg","w":1000,"h":667,"alt":"A woman at a laptop taking part in a video conference","cap":"A young woman joins a video call from her laptop. Remote and hybrid workers rely on calls like this to stay connected to their team.","by":"Bluestonex","title":"Real world:"},{"screen":"Collaboration, production and the creator economy","src":"img/notes/n_C5GeaRZp2D4.jpg","w":1000,"h":667,"alt":"A whiteboard covered with sticky notes for planning social media content","cap":"A team plans its social media content on a whiteboard. Collaboration and planning like this sit at the heart of production in the creator economy.","by":"Walls.io","title":"Real world:"},{"screen":"Professionalism, globalisation and change","src":"img/notes/n_5-BG0pEoE_8.jpg","w":1000,"h":667,"alt":"A hand placing push pins into a world map","cap":"Someone places pins across a world map. Digital media professionals now work with clients and audiences in many countries, so professionalism must travel across borders.","by":"GeoJango Maps","title":"Real world:"},{"screen":"Core, digital and research skills","src":"img/notes/n_nYToduYJH-c.jpg","w":1000,"h":667,"alt":"People studying at long tables inside a grand public library","cap":"People study in the New York Public Library. Research skills, from finding sources to checking facts, are core skills for any digital media worker.","by":"Clay Banks","title":"Real world:"},{"screen":"Entrepreneurial skills and the full landscape","src":"img/notes/n_5H0p6JPUHbI.jpg","w":1000,"h":667,"alt":"People talking and smiling together in a lobby after an event","cap":"People chat in a lobby after an event. Networking, confidence and spotting opportunities are entrepreneurial skills that help creators turn ideas into businesses.","by":"Product School","title":"Real world:"},{"screen":"Professional dispositions","src":"img/notes/n_NzIV4vOBA7s.jpg","w":1000,"h":667,"alt":"Two people shaking hands over a wooden table","cap":"Two people shake hands across a table. Reliability, respect and integrity are professional dispositions that build trust with clients and collaborators.","by":"Rock Staar","title":"Real world:"},{"screen":"Continuous learning and both matter","src":"img/notes/n_Imz-pn2LMbg.jpg","w":1000,"h":667,"alt":"A young woman wearing headphones studying at a desk","cap":"A young woman studies with headphones on. Tools and platforms change constantly, so continuous learning keeps both skills and dispositions up to date.","by":"Julio Lopez","title":"Real world:"}],"M2U5":[{"screen":"Analysing the environment: PEST plus culture","src":"img/notes/n_3NboWTtsV2k.jpg","w":1000,"h":667,"alt":"A man sitting on a concrete bench beside a metal fence on a city street","cap":"A man makes a living on a street in Havana, Cuba. Laws, the economy, society, technology and culture all shape what people can do, which is what a PEST plus culture analysis examines.","by":"Nick Karvounis","title":"Real world:"},{"screen":"Regional challenges","src":"img/notes/n_PmBNVq4ninQ.jpg","w":1000,"h":668,"alt":"A utility pole knocked over by storm winds lying across damaged ground","cap":"A pole knocked over by Super Typhoon Odette in Cebu, Philippines. Island regions face the same risk: storms can cut power and networks for days, a key regional challenge.","by":"Carl Kho","title":"Real world:"},{"screen":"Regional and global opportunities","src":"img/notes/n_TpL3BnJ3ZAQ.jpg","w":1000,"h":667,"alt":"A crowd waving colourful flags, including the flag of Barbados, at a lively festival","cap":"A festival crowd waves flags, including that of Barbados. Caribbean music and festivals have a distinctive voice that can reach wider regional and global audiences online.","by":"Kyle Hinkson","title":"Real world:"},{"screen":"Public engagement via digital media","src":"img/notes/n_OFhVojFaZmE.jpg","w":1000,"h":667,"alt":"Two microphones set up on a table for a panel discussion","cap":"Two microphones are ready for a panel discussion. Live-streamed briefings and public discussions are ways governments and organisations inform and consult the public through digital media.","by":"Mika Baumeister","title":"Real world:"},{"screen":"Policy, economic, social and technological factors","src":"img/notes/n_SsAFdirwkXc.jpg","w":1000,"h":666,"alt":"Telecom towers with antennas standing on a hilltop","cap":"Telecom towers on Winter Hill in Bolton, UK. Infrastructure like this is part of the technological factor, deciding how fast and how widely digital content can reach people.","by":"David Arrowsmith","title":"Real world:"},{"screen":"Four regional challenges","src":"img/notes/n_YW4zhg0iZaM.jpg","w":1000,"h":667,"alt":"The silhouette of a man mending fishing nets by the sea at sunset","cap":"A fisherman mends nets at sunset in Grand Mal, Grenada. Creators in smaller coastal and rural communities can face uneven connectivity and high costs when producing and sharing content.","by":"Hugh Whyte","title":"Real world:"},{"screen":"Opportunities and cultural advantage","src":"img/notes/n_RAZ4ArwfydM.jpg","w":1000,"h":667,"alt":"Women in colourful costumes parading at a festival","cap":"Costumed masqueraders at Chaguanas Carnaval 2025. Rich Caribbean culture like this gives regional creators distinctive content that global audiences seek out.","by":"Anton Acosta","title":"Real world:"}],"M2U6":[{"screen":"Debt and equity: the two basic types","src":"img/notes/n_GtX2ljDPyPI.jpg","w":1000,"h":667,"alt":"A glass jar holding dollar bills with coins spilled across a table","cap":"A jar of notes and coins spills onto a table. Every project needs money, raised either by borrowing it (debt) or by selling a share of ownership (equity).","by":"Sasun Bughdaryan","title":"Real world:"},{"screen":"Other types of funding","src":"img/notes/n_miWvkqLXxGw.jpg","w":1000,"h":667,"alt":"A small blue shopfront with many items on display","cap":"A small shop with its goods on display. Small ventures like this often rely on grants, sponsorship, community support or pre-sales rather than only bank loans.","by":"Asael Peña","title":"Real world:"},{"screen":"Sources of funding","src":"img/notes/n_lZXX-QVdyXY.jpg","w":1000,"h":563,"alt":"Two businessmen shaking hands across a café table after signing a contract","cap":"Two businessmen shake hands after signing a contract. An investor or lender is a source of funding, the person or organisation who actually provides the money.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Creator income models","src":"img/notes/n_VIQKDL6-TpU.jpg","w":1000,"h":667,"alt":"A young woman holding up a phone in front of a bright light","cap":"A young creator films with her phone in front of a light. Creators keep going through income models such as advertising, affiliate links, memberships and brand deals.","by":"siddharth vyas","title":"Real world:"},{"screen":"Ten types of funding","src":"img/notes/n_SoqG9RWd_FA.jpg","w":1000,"h":667,"alt":"Looking down into a jar full of saved silver coins","cap":"Loose change saved in a money jar. Funding can come in many forms, from loans and grants to donations, crowdfunding and pre-sales, each adding to the pot.","by":"Nick Fewings","title":"Real world:"},{"screen":"Debt vs equity","src":"img/notes/n_OQMZwNd3ThU.jpg","w":1000,"h":668,"alt":"A man signing a paper document at a desk","cap":"A man signs a document. Taking a loan means signing to repay with interest, while equity means signing away a share of ownership in return for money.","by":"Scott Graham","title":"Real world:"},{"screen":"Four groups of funding sources","src":"img/notes/n_Skfy8ljB7X4.jpg","w":1000,"h":667,"alt":"A large stone bank building with columns and a flag on the corner","cap":"The Federal Reserve Bank building in Chicago. Banks and other lending institutions are one group of funding sources, offering loans that must be repaid.","by":"Joshua Woroniecki","title":"Real world:"},{"screen":"Creator income and platform monetisation","src":"img/notes/n_1EJtf5wWlgg.jpg","w":1000,"h":667,"alt":"Two women serving customers at a busy market stall selling goods","cap":"Two women serve customers at a busy market stall. Selling branded goods directly to fans is the same idea as merchandising, one of the creator income models alongside ads and sponsorships.","by":"Zheng Yijun","title":"Real world:"}],"M2U7":[{"screen":"What a proposal is for","src":"img/notes/n_505eectW54k.jpg","w":1000,"h":667,"alt":"A hand writing with a ballpoint pen in an open notebook","cap":"Someone writes out ideas in a notebook. A proposal turns ideas like these into a clear written plan that funders and clients can approve.","by":"Thought Catalog","title":"Real world:"},{"screen":"The elements of a proposal (a) to (f)","src":"img/notes/n_yW-Qgw_IJXg.jpg","w":1000,"h":667,"alt":"A silver laptop beside a sheet of ruled paper on a desk","cap":"A laptop sits beside ruled paper in a mobile workspace. Writing the title page, summary, aims and background of a proposal starts with drafting like this.","by":"Maya Maceka","title":"Real world:"},{"screen":"The elements of a proposal (g) to (k)","src":"img/notes/n_8k5j5z6ZYT4.jpg","w":1000,"h":563,"alt":"Two colleagues reviewing reports together at a table in a modern office","cap":"Two colleagues go over reports together. Timelines, resources, evaluation and appendices are the later proposal elements that reviewers check closely.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Outlining a budget","src":"img/notes/n_xoU52jUVUXA.jpg","w":1000,"h":574,"alt":"A person holding a paper beside a pen and calculator","cap":"A person checks figures with a calculator and pen. Outlining a budget means listing every cost, from equipment to people, and totalling it accurately.","by":"Kelly Sikkema","title":"Real world:"},{"screen":"The proposal in five groups","src":"img/notes/n_UtIr_UaiDmg.jpg","w":1000,"h":563,"alt":"A team brainstorming with sticky notes on a glass wall","cap":"A team arranges sticky notes on a glass wall. Grouping ideas like this mirrors how a proposal's eleven elements fit into five clear groups.","by":"Vitaly Gariev","title":"Real world:"}],"M2U8":[{"screen":"What is agile?","src":"img/notes/n_p0xDCNg3cw8.jpg","w":1000,"h":668,"alt":"A woman holding sticky notes in front of a task board","cap":"A scrum master works with a kanban board. Agile breaks a project into small tasks that the team plans, builds and reviews in short cycles.","by":"Parabol","title":"Real world:"},{"screen":"The agile model: five phases","src":"img/notes/n_OXmym9cuaEY.jpg","w":1000,"h":786,"alt":"Hands holding three sticky notes labelled To Do, Doing and Done","cap":"Three sticky notes read To Do, Doing and Done. Work moves through clear phases in the agile model, with each task tracked from start to finish.","by":"Eden Constantino","title":"Real world:"},{"screen":"Agile tools you can use","src":"img/notes/n_v89zhr0iBFY.jpg","w":1000,"h":667,"alt":"Two people arranging yellow sticky notes on a glass wall roadmap","cap":"Two people plan a roadmap with sticky notes on a glass wall. Kanban boards and roadmaps are simple agile tools any student team can use.","by":"airfocus","title":"Real world:"},{"screen":"Pitching a digital media project","src":"img/notes/n_4wSnhAT8d9g.jpg","w":1000,"h":663,"alt":"A man presenting and pointing to a whiteboard covered in sticky notes","cap":"A man presents ideas at a whiteboard in a meeting room. Pitching means explaining a project clearly and persuasively so others want to back it.","by":"Paymo","title":"Real world:"},{"screen":"The 4Ps of marketing in a pitch","src":"img/notes/n_vbeFYH1Oz34.jpg","w":1000,"h":667,"alt":"A street vendor selling drinks from a mobile cart","cap":"A street vendor sells drinks from a cart. Even here the 4Ps apply: the product, its price, the place it is sold and how it is promoted.","by":"Sergio Aguirre","title":"Real world:"},{"screen":"Agile as a continuous loop","src":"img/notes/n_WC6MJ0kRzGw.jpg","w":1000,"h":667,"alt":"A hand holding a pink sticky note that reads Run a usability test","cap":"A sticky note reads \"Run a usability test\". In agile, testing feeds back into planning, so the cycle loops round again and again.","by":"David Travis","title":"Real world:"},{"screen":"What happens in each phase","src":"img/notes/n_S3JdHNXSfnA.jpg","w":1000,"h":667,"alt":"A wall covered with yellow and orange sticky notes from a design sprint","cap":"A wall of sticky notes from a design sprint. Each phase of agile, from planning to review, leaves a visible trail of tasks and decisions.","by":"Will H McMahan","title":"Real world:"},{"screen":"Elements of a winning pitch","src":"img/notes/n_MsCiikhkx1Y.jpg","w":1000,"h":667,"alt":"A single microphone on a stand against a pale background","cap":"A microphone stands ready for a speaker. A winning pitch needs a clear problem, a strong solution, a known audience and a confident delivery.","by":"Akshay Chauhan","title":"Real world:"},{"screen":"Module 2 at a glance","src":"img/notes/n_ETRPjvb0KM0.jpg","w":1000,"h":667,"alt":"Colourful sticky notes pinned to a board after a brainstorm","cap":"Colourful notes pinned to a board after a brainstorm. Module 2 gathers many ideas, from digital users to value chains, work and project management, into one connected picture.","by":"Patrick Perkins","title":"Real world:"}],"M3U1":[{"screen":"What is the creative design process?","src":"img/notes/n_qC2n6RQU4Vw.jpg","w":1000,"h":667,"alt":"A person writing and sketching ideas on white paper during a design session","cap":"A designer works through ideas on paper during a design session. A repeatable creative design process moves from a problem to a tested solution, so good ideas do not depend on luck.","by":"UX Indonesia","title":"Real world:"},{"screen":"The seven stages of the creative design process","src":"img/notes/n_qWwpHwip31M.jpg","w":1000,"h":667,"alt":"A person arranges blue and white paper notes mapping an app's flow on a board.","cap":"A software designer reviews a wall of notes mapping the flow of an app for field staff. Laying the work out step by step mirrors the seven stages, from accepting and analysing the problem through to implementing and evaluating the solution.","by":"Alvaro Reyes","title":"Real world:"},{"screen":"Design thinking and the core principles of design","src":"img/notes/n_R3jJvOSzjrk.jpg","w":1000,"h":667,"alt":"Three people in a design studio discussing notes on a whiteboard, one pointing","cap":"A team discusses notes on a whiteboard in a design studio. Defining a clear, user-focused problem statement together is the 'Define' stage of design thinking.","by":"Jud Mackrill","title":"Real world:"},{"screen":"Ideation and concept formulation","src":"img/notes/n_BoAbPMRKLS0.jpg","w":1000,"h":667,"alt":"A blue marker lying beside a pad of yellow sticky notes","cap":"Sticky notes and a marker are the classic brainstorming kit. Ideation values quantity first: jot one idea per note, then group and select the strongest to form a concept.","by":"Kelly Sikkema","title":"Real world:"},{"screen":"Problems, solution design, validation and iteration","src":"img/notes/n_5QgIuuBxKwM.jpg","w":1000,"h":667,"alt":"Two people talk across a table with a laptop open, one gesturing while explaining.","cap":"A designer listens to a customer explain the problems they face. Conversations like this help define the problem clearly and later validate whether a solution really works for its users before it is refined and improved.","by":"Headway","title":"Real world:"},{"screen":"Gestalt: how the eye groups what it sees","src":"img/notes/n_cX0Yxw38cx8.jpg","w":1000,"h":616,"alt":"A flock of dark bird silhouettes flying against a pale sky.","cap":"A flock of birds flies across a pale sky. The eye reads the separate birds as one group because they are close together and look alike, showing the Gestalt principles of proximity and similarity at work.","by":"Mehdi Sepehri","title":"Real world:"},{"screen":"The seven core design principles","src":"img/notes/n_7jM8GPL-4oc.jpg","w":1000,"h":665,"alt":"A single red bottle on a small round metal table, lit by a slice of light in a dark room.","cap":"A single red bottle stands in a slice of light in a dark room. Strong contrast of colour and light makes it the instant focal point, showing how contrast stops elements competing so one thing clearly wins.","by":"Chloë Forbes-Kindlen","title":"Real world:"},{"screen":"Composition: entry points, visual weight and reading patterns","src":"img/notes/n_3bCASwf1MnE.jpg","w":1000,"h":667,"alt":"A person holds an open magazine, reading a page spread.","cap":"A reader holds an open magazine spread. Magazine layouts guide the eye along predictable paths such as the C-pattern, so designers place the most important content where readers' eyes already travel.","by":"Vision Magazin","title":"Real world:"}],"M3U2":[{"screen":"Four models of implementation","src":"img/notes/n_jL2CthCvS1A.jpg","w":1000,"h":667,"alt":"A small waterfall flowing down a series of rocky steps in a forest.","cap":"Water flows down a waterfall one rocky step at a time and never back up. This is a helpful picture of the linear (waterfall) model, where each stage is finished before the next begins and there is no going back.","by":"Alexander Pell","title":"Real world:"},{"screen":"Linear vs non-linear; solo vs collaborative","src":"img/notes/n_O2-EZNGZIyk.jpg","w":1000,"h":563,"alt":"A computer monitor showing a video editing timeline with clips and audio tracks","cap":"A video editing timeline on screen. In a non-linear editor any clip can be moved anywhere on the timeline without re-recording, unlike old tape-to-tape linear editing.","by":"Onur Binay","title":"Real world:"},{"screen":"Agile and scrum in media production","src":"img/notes/n_8hDDPavjW2o.jpg","w":1000,"h":667,"alt":"A woman holding a phone stands beside a kanban board of notes during a planning session.","cap":"A team member stands by a kanban board during a planning and prioritisation session. Agile teams use boards like this as a product backlog, choosing which items to finish in each short sprint.","by":"airfocus","title":"Real world:"},{"screen":"Mood boards, storyboards and wireframes","src":"img/notes/n_HszbGgaGjOg.jpg","w":1000,"h":667,"alt":"Printed images, scissors and materials laid out on a table for a mood board.","cap":"Printed pictures, scissors and materials are gathered for a mood board. A paper collage like this captures the look and feel of a project, helping a designer agree a style with a client before production begins.","by":"Fiona Murray-deGraaff","title":"Real world:"},{"screen":"Wireframes, mock-ups and prototypes: from structure to experience","src":"img/notes/n_v9FQR4tbIq8.jpg","w":1000,"h":667,"alt":"A woman's hands sketching a wireframe layout on paper.","cap":"A designer's hands draw a wireframe on paper. This low-fidelity stage answers where everything goes and how users move between screens, before colour and detail are added in a mock-up or clickable prototype.","by":"Kelly Sikkema","title":"Real world:"},{"screen":"Using each stage well","src":"img/notes/n_Jz6ol2vASgw.jpg","w":1000,"h":667,"alt":"A pink pencil on grid paper covered with hand-drawn website wireframe sketches","cap":"Hand-drawn website wireframes on grid paper. Boxes and lines show the layout and navigation without colours or fonts, so reviewers comment on how the page works.","by":"Vitalii Abakumov","title":"Real world:"},{"screen":"Feedback loops and peer critique","src":"img/notes/n_XZkk5xT8Xrk.jpg","w":1000,"h":750,"alt":"A group of adult students working on laptops and talking around a large table","cap":"Students discuss their work around a shared table. Structured peer critique, such as TAG or 'I like / I wonder / What if', turns these conversations into a useful feedback loop.","by":"Product School","title":"Real world:"}],"M3U3":[{"screen":"Local problems, global-quality solutions","src":"img/notes/n_KIfVGXf6Kzc.jpg","w":1000,"h":562,"alt":"Coastal town of Gouyave in St John, Grenada, with houses along the shoreline","cap":"Gouyave, a coastal town in St John, Grenada. Communities like this one face real local problems, and designers who understand them can create solutions that meet global standards of quality.","by":"Hugh Whyte","title":"Real world:"},{"screen":"Framing problems as design opportunities","src":"img/notes/n_kFP7tQSL36w.jpg","w":1000,"h":520,"alt":"Four colourful waste and recycling bins standing in a row","cap":"Four colour-coded bins for sorting waste. Turning 'people litter' into 'how might we make sorting rubbish easy?' frames a problem as a design opportunity, and colour and labelling become the solution.","by":"Jonathan Cosens Photography","title":"Real world:"},{"screen":"Research methods: surveys, interviews and observation","src":"img/notes/n_eF7HN40WbAQ.jpg","w":1000,"h":667,"alt":"Two women sitting across a table talking in an interview","cap":"Two women talking face to face across a table. A one-to-one interview like this gathers rich qualitative detail about users' needs, complementing the numbers from surveys and what you notice through observation.","by":"Christina","title":"Real world:"},{"screen":"Four ways to arrive at creative solutions","src":"img/notes/n_qFpnvZ_j9HU.jpg","w":1000,"h":750,"alt":"A wall covered in rows of colourful sticky notes","cap":"A wall covered in sticky notes. Capturing many ideas, then grouping, combining and adapting them, is one practical way designers arrive at creative solutions rather than settling on the first idea.","by":"Hugo Rocha","title":"Real world:"},{"screen":"Implementation and Caribbean case studies","src":"img/notes/n_9J3opB-2dRE.jpg","w":1000,"h":666,"alt":"Brown sargassum seaweed washed up along the shore at Parque Isla de Cabras, Puerto Rico","cap":"Sargassum seaweed piled on the shore at Parque Isla de Cabras, Puerto Rico. Sargassum is a shared Caribbean problem, and real case studies of tackling it show how a design idea is implemented and tested.","by":"Erick Morales Oyola","title":"Real world:"}],"M3U4":[{"screen":"The role of pre-production and the project brief","src":"img/notes/n_HGb4SO8J2Wo.jpg","w":1000,"h":750,"alt":"Flat lay of a camera beside an open notebook on a table","cap":"A camera beside an open notebook. Before any shooting begins, pre-production means writing down the brief: the client, audience, purpose, budget and deadline that every later decision must serve.","by":"Laura Ohlman","title":"Real world:"},{"screen":"Core pre-production elements","src":"img/notes/n_Eq_dtBylgoE.jpg","w":1000,"h":667,"alt":"A small film crew working with a camera and boom microphones","cap":"A film crew with a camera and microphones. Crew, equipment, locations and casting are all core pre-production elements that must be arranged before the shoot day.","by":"Ryan Joseph","title":"Real world:"},{"screen":"Factors affecting production","src":"img/notes/n_OWxeIPIKwrY.jpg","w":1000,"h":664,"alt":"Aerial view of the islands of St Kitts and Nevis surrounded by sea","cap":"St Kitts and Nevis seen from above. On small islands, location, travel between sites, weather and access to equipment are real factors that shape a production's schedule and budget.","by":"Holger Woizick","title":"Real world:"},{"screen":"Scripts, storyboards, shot types and schedules","src":"img/notes/n_aYDIuBWzSc4.jpg","w":1000,"h":667,"alt":"Film clapperboard marked Take 3 held in front of a camera","cap":"A clapperboard showing 'Take 3'. Each scene, shot and take on the slate matches the script, storyboard and shot list, so the schedule can be followed and footage found later.","by":"Leuchtturm Entertainment","title":"Real world:"},{"screen":"Rule of thirds, composition and framing","src":"img/notes/n_hz8sbSg2nU0.jpg","w":1000,"h":714,"alt":"Old crumbling concrete pier stretching into a calm Caribbean Sea under a clear sky","cap":"An old concrete pier stretching into the calm Caribbean Sea. Its strong leading lines and minimal framing draw the eye into the picture, showing how placement and composition guide the viewer.","by":"Ocho Artex Media","title":"Real world:"},{"screen":"Film language: thinking like a director","src":"img/notes/n_xS1ujVJbDRM.jpg","w":1000,"h":667,"alt":"A man holding a video camera, ready to film","cap":"A camera operator holding a video camera. Every choice of where to point it, how close to get and when to move is part of film language, the visual grammar a director uses to tell the story.","by":"Jakob Owens","title":"Real world:"},{"screen":"Shot sizes: from extreme long shot to extreme close-up","src":"img/notes/n_SNRtwswzmMo.jpg","w":1000,"h":563,"alt":"A tiny figure standing on a cliff in a vast desert landscape","cap":"A lone figure dwarfed by a desert landscape. This is an extreme long shot: the setting dominates and the person is tiny, the opposite end of the scale from an extreme close-up of an eye or hand.","by":"sayan Nath","title":"Real world:"},{"screen":"Camera angles and what they say","src":"img/notes/n_FlVA1nqTBAc.jpg","w":1000,"h":800,"alt":"Low-angle view looking up at a man standing on a wall against the sky","cap":"A man photographed from below as he stands on a wall. A low angle like this makes a subject look taller and more powerful, while a high angle looking down tends to make them seem smaller or vulnerable.","by":"Souhail BIDA","title":"Real world:"},{"screen":"Camera movement: every move has a motive","src":"img/notes/n_I3vtrgL1EwM.jpg","w":1000,"h":563,"alt":"Young filmmaker outdoors holding a camera mounted on a handheld gimbal stabiliser","cap":"A filmmaker holding a camera on a gimbal stabiliser. Gimbals allow smooth tracking and following moves, but each movement should have a motive, such as following a character or revealing new information.","by":"Sanket Mishra","title":"Real world:"},{"screen":"Staging and blocking: power, distance and depth","src":"img/notes/n_ZOeVIjScKpY.jpg","w":1000,"h":750,"alt":"Actors performing a scene on a dimly lit theatre stage","cap":"Actors performing a scene on a theatre stage. Where each performer stands, how far apart they are and who is nearer the audience is blocking, and it signals power, closeness and tension in film just as on stage.","by":"Zara Photo","title":"Real world:"},{"screen":"Continuity and the 180-degree rule","src":"img/notes/n_K8XYGbw4Ahg.jpg","w":1000,"h":667,"alt":"Two people sitting across a table from each other holding grey mugs","cap":"Two people facing each other across a table with mugs. Filming a conversation like this, the camera stays on one side of the line between them (the 180-degree rule) and props such as the mugs must match from shot to shot.","by":"Priscilla Du Preez","title":"Real world:"},{"screen":"Narrative structure: the three-act arc","src":"img/notes/n_CP0XLYNI2B4.jpg","w":1000,"h":665,"alt":"Dark theatre stage with closed purple curtains and microphone stands at the front","cap":"A theatre stage with its curtains closed before a performance. Stories have long been built in acts: a set-up, a confrontation that builds tension, and a resolution, the three-act arc that most films still follow.","by":"Camille Roux","title":"Real world:"},{"screen":"Lighting tones and genre mood","src":"img/notes/n_1DMss8Mf70Q.jpg","w":1000,"h":667,"alt":"Black and white photo of a man in a dark room with strong shadows","cap":"A man in a dark room, lit so that most of the frame falls into shadow. This low-key lighting creates the tense, mysterious mood of thrillers and film noir, whereas bright high-key lighting suits comedy.","by":"Jared Brashier","title":"Real world:"},{"screen":"Storyboarding conventions","src":"img/notes/n_bNjYwZrkJ3A.jpg","w":1000,"h":668,"alt":"Sketchbook page with a pencil drawing of a person sitting at a table","cap":"A pencil sketch of a person seated at a table. Storyboard frames are quick drawings like this, with arrows, shot sizes and notes added so the whole crew can see how each shot should look.","by":"Nasim Keshmiri","title":"Real world:"},{"screen":"From script to storyboard to shoot","src":"img/notes/n_WAchuh1Gc-0.jpg","w":1000,"h":667,"alt":"Close-up of the pages of a printed screenplay","cap":"The printed pages of a screenplay. The script is the starting point: it is broken down into a storyboard and shot list, which then guide the schedule and the work on the shoot day.","by":"Waldemar Brandt","title":"Real world:"},{"screen":"Lighting and the psychology of colour","kind":"example","title":"Warm light: golden hour on a face","tag":"Warm","html":"<p>Low evening sun gives skin and hair a deep orange-red glow (<span class=\"hexchip\" style=\"--c:#661502\"><i></i>#661502</span>, <span class=\"hexchip\" style=\"--c:#B76808\"><i></i>#B76808</span>). Warm light feels intimate, nostalgic and romantic.</p><p>Directors film emotional reunions, love scenes and happy endings in light like this, often deliberately waiting for golden hour.</p>","q":null,"wide":false,"pal":[["#661502",18,"dark red"],["#b76808",3,"orange"],["#eeba5e",1,"orange"],["#f8f4e7",17,"near white"]],"w":667,"h":1000,"by":"Zulfugar Karimov","alt":"A woman wearing glasses looking up into warm golden hour light","cap":"Warm light: golden hour on a face","src":"img/notes/c_fmuBuRzRiko.jpg"},{"screen":"Lighting and the psychology of colour","kind":"example","title":"Cool light: a harbour at blue hour","tag":"Cool","html":"<p>Just before sunrise the whole scene is dark teal (<span class=\"hexchip\" style=\"--c:#29444B\"><i></i>#29444B</span>). Cool, low light feels lonely, mysterious or sad.</p><p>Crime dramas and thrillers often grade their footage towards teal and blue for exactly this effect.</p>","q":null,"wide":false,"pal":[["#29444b",22,"dark muted cyan"],["#06292e",42,"near black"]],"w":1000,"h":667,"by":"Christian Lue","alt":"A dark silhouette of a bridge over water with industrial cranes in the distance","cap":"Cool light: a harbour at blue hour","src":"img/notes/c_fl4OL3Hqisw.jpg"},{"screen":"Lighting and the psychology of colour","kind":"example","title":"Dark, heavy light: a storm","tag":"Threat","html":"<p>Storm clouds block the sun and drain colour from the scene. Low-key, desaturated light like this signals danger. Caribbean audiences know this sky well from hurricane season, so it carries real emotional weight here.</p>","q":null,"wide":false,"pal":[["#313941",15,"dark muted blue"],["#464f5c",36,"muted blue"],["#5c6675",18,"grey"],["#dcd1ca",9,"light muted orange"]],"w":750,"h":1000,"by":"Raychel Sanner","alt":"A paved road stretching toward the horizon under a heavy, dark storm sky","cap":"Dark, heavy light: a storm","src":"img/notes/c_MnnXMvs4cQo.jpg"},{"screen":"Colour psychology in branding and culture","kind":"example","title":"Red, gold and green in Grenada","tag":"Culture","html":"<p>Grenada's flag, painted on a tree trunk, uses red, gold and green. These colours also belong to the Pan-African movement and to Rastafari, so they carry pride and history for many people in the region.</p><p>A brand that borrows them must do so with respect: they are not just decoration.</p>","q":null,"wide":true,"pal":[["#9a3545",5,"red"],["#e8ce5f",6,"yellow-orange"],["#05a58b",4,"teal"],["#0a0d0b",16,"near black"]],"w":905,"h":1000,"by":"Hugh Whyte","alt":"a flag painted on the bark of a tree","cap":"Red, gold and green in Grenada","src":"img/notes/c_UmlSwpCmQXw.jpg"},{"screen":"Colour psychology in branding and culture","kind":"example","title":"Violet at Trinidad Carnival","tag":"Culture","html":"<p>This violet and silver King costume from Port of Spain shows how carnival designers use colour to express a whole theme. Purple suggests royalty, mystery and spectacle.</p><p>In Caribbean culture, carnival colour is bold, joyful and deliberate: a key reference for designers making festival branding.</p>","q":null,"wide":false,"pal":[["#a493c4",13,"muted violet"],["#7759b3",5,"violet"],["#4e31a5",3,"violet"],["#833088",1,"magenta"]],"w":1000,"h":664,"by":"Holger Woizick","alt":"a woman in a purple costume with feathers on her head","cap":"Violet at Trinidad Carnival","src":"img/notes/c_78z3qaiYN8I.jpg"},{"screen":"Colour psychology in branding and culture","kind":"example","title":"Blue: trust and the sea","tag":"Branding","html":"<p>Turquoise water says calm, clean and safe. Banks and telecoms use blue to suggest trust; Caribbean tourism uses it because it is simply our sea.</p>","q":null,"wide":false,"pal":[["#088da7",42,"cyan"],["#3cc1d6",18,"cyan"],["#076882",18,"dark cyan"]],"w":1000,"h":750,"by":"Héctor Mavare","alt":"A boat travels across blue water","cap":"Blue: trust and the sea","src":"img/notes/c_E0OVNeeCDBk.jpg"},{"screen":"Colour psychology in branding and culture","kind":"example","title":"Red: heat and urgency","tag":"Branding","html":"<p>Hot peppers at a market: red signals heat, energy and urgency. That is why so many food brands and \"Sale\" banners use red, and why it should be used sparingly in an interface.</p>","q":null,"wide":false,"pal":[["#81100b",18,"dark red"],["#bc2018",8,"red"],["#9f8f79",17,"muted orange"]],"w":750,"h":1000,"by":"Jonathan Borba","alt":"Plates of red chili peppers displayed at a market","cap":"Red: heat and urgency","src":"img/notes/c_M7swW5Iy8cs.jpg"},{"screen":"Colour psychology in branding and culture","kind":"example","title":"Yellow: optimism in Aruba","tag":"Branding","html":"<p>A sunshine-yellow wall against a blue sky: happy, warm, holiday. Yellow is highly visible, so it works for highlights and warnings, but yellow text on white is hard to read.</p>","q":null,"wide":false,"pal":[["#c2b206",68,"yellow"],["#44b0ea",6,"blue"],["#dfeff7",8,"near white"]],"w":800,"h":1000,"by":"Olivier Piquer","alt":"yellow painted house","cap":"Yellow: optimism in Aruba","src":"img/notes/c_cjUfCXF201U.jpg"}],"M3U5":[{"screen":"What are digital media tools?","src":"img/notes/n_ezPGfAMES60.jpg","w":1000,"h":714,"alt":"A hand using a digital stylus on a tablet to edit a photo","cap":"A hand using a stylus on a tablet to edit a photograph. The tablet, stylus and editing app together are digital media tools: hardware and software used to create, edit and share media.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"Tools by task","src":"img/notes/n_2mZncc1MQX4.jpg","w":1000,"h":667,"alt":"Flat lay of camera bodies, lenses and accessories arranged on a surface","cap":"Camera gear laid out piece by piece. Grouping tools by the task they serve, such as capturing, recording sound or editing, helps a creator choose the right kit for each stage of a project.","by":"Micah & Sammie Chaffin","title":"Real world:"},{"screen":"Advantages and disadvantages: the criteria","src":"img/notes/n_qjA7KQQIFS8.jpg","w":1000,"h":667,"alt":"A pen display tablet and a laptop set up together on a desk","cap":"A pen display connected to a laptop. Before buying a tool like this, weigh the criteria: cost, compatibility with your computer, ease of use and whether its features do the job.","by":"Daniele Luciani","title":"Real world:"},{"screen":"AI-assisted tools: uses and limits","src":"img/notes/n_3bHtiDpjAS8.jpg","w":1000,"h":667,"alt":"A person using a smartphone with a city skyline in the background","cap":"A person using a smartphone above a city. Many phone and editing apps now include automated assistant features; they can speed up work, but a creator must still check accuracy, originality and permission.","by":"Zulfugar Karimov","title":"Real world:"},{"screen":"Evaluating utility: a decision matrix","src":"img/notes/n_JXyY3jRV9oI.jpg","w":1000,"h":663,"alt":"A whiteboard covered with project planning notes and columns","cap":"A whiteboard laid out in columns for planning. A decision matrix uses the same idea: list the tools in rows, the criteria in columns, then score each one to see which is most useful.","by":"Paymo","title":"Real world:"},{"screen":"Page layout software: InDesign, Affinity Publisher, Canva and Scribus","src":"img/notes/n_g_w1Ndvq3Z0.jpg","w":1000,"h":750,"alt":"An open printed brochure with text and images lying on a wooden surface","cap":"An open brochure combining text and pictures. Printed pieces like this are built in page layout software, which places text frames, images and margins precisely before the file is sent to print.","by":"Sergio Alcázar Mondéjar","title":"Real world:"},{"screen":"Core image-editing concepts in any editor","src":"img/notes/n_6UI5_1ADPk4.jpg","w":1000,"h":667,"alt":"A laptop on a desk showing photo editing software with a portrait on screen","cap":"A laptop running photo editing software. Whatever the program, the same core ideas apply: layers, selections, cropping, exposure and colour adjustments, and saving a non-destructive working file.","by":"an.nemopo","title":"Real world:"}],"M3U6":[{"screen":"Methods of digital communication","src":"img/notes/n_6aIPkbZ7zrU.jpg","w":1000,"h":750,"alt":"A smartphone showing a messaging app conversation","cap":"A smartphone open on a messaging app. Instant messaging is one of many methods of digital communication, alongside email, video calls, social media and websites, each suited to different messages.","by":"Franck","title":"Real world:"},{"screen":"Digital sharing strategies and the cloud","src":"img/notes/n_M5tzZtFCOfs.jpg","w":1000,"h":561,"alt":"Rows of network cables plugged into server equipment","cap":"Network cables connect racks of servers. The cloud is not really in the sky: shared files live on providers' servers like these and are reached over the internet from any device.","by":"Taylor Vick","title":"Real world:"},{"screen":"Audience, purpose, message: choosing tone, tools and platforms","src":"img/notes/n_TEvoVj1Gey0.jpg","w":1000,"h":667,"alt":"A wooden dock over clear blue water at Mangel Halto beach","cap":"Clear water and a wooden dock at Mangel Halto, Aruba. A reef campaign would show the same place in different tones: evidence-based for sponsors, playful and visual on social media.","by":"Vera Wijermars","title":"Real world:"},{"screen":"Storytelling, cross-cultural communication and accessibility","src":"img/notes/n_NyEcJXFOz6A.jpg","w":1000,"h":667,"alt":"Young students in red vests and white shirts practising sign language","cap":"Young students practising sign language. Accessible communication means planning for every audience, for example adding captions, sign interpretation or alt text so that deaf or blind viewers can follow the story too.","by":"Assad Tanoli","title":"Real world:"},{"screen":"Classifying typefaces","src":"img/notes/n_Sxs2E3QYoJ4.jpg","w":1000,"h":667,"alt":"Antique printing trays divided into compartments filled with metal type","cap":"Antique type cases filled with metal letters. Printers sorted type by style and size, and designers still classify typefaces into families such as serif, sans serif, script and display.","by":"Fabian Kleiser","title":"Real world:"},{"screen":"The anatomy of type","src":"img/notes/n_JzcEdsEy1hg.jpg","w":1000,"h":776,"alt":"Close-up of antique wooden letterpress type blocks","cap":"A close-up of wooden letterpress blocks. Seen this large, the parts of each letter are easy to spot: stems, bowls, counters, serifs, and the baseline every character sits on.","by":"Declan Sun","title":"Real world:"},{"screen":"Micro-typography: kerning, tracking, leading and measure","src":"img/notes/n_1lJK8AO1BI4.jpg","w":1000,"h":750,"alt":"A hand picking a piece of metal type from a type case","cap":"A hand selecting metal type from a case. Hand typesetters adjusted the space between letters and lines with physical spacers; kerning, tracking and leading are the digital versions of that same fine spacing.","by":"kaori kubota","title":"Real world:"},{"screen":"Typographic conventions","src":"img/notes/n_L9-1gjQKr8I.jpg","w":1000,"h":667,"alt":"An open magazine article with a photo of a laughing woman and columns of text","cap":"An open magazine article. It follows familiar typographic conventions, such as a clear headline, readable body text in columns and consistent styles, so readers know at once how to read the page.","by":"Content Pixie","title":"Real world:"},{"screen":"Pairing typefaces, legibility and accessible type","src":"img/notes/n_sOdzJEsGDLA.jpg","w":1000,"h":667,"alt":"A signpost with several direction arrows against a blue sky","cap":"A signpost with several direction arrows. Signs must be read quickly from a distance, a clear test of legibility: simple letterforms, strong contrast and sensible size make type accessible to everyone.","by":"Ian Ward","title":"Real world:"},{"screen":"Page layout with grids","src":"img/notes/n_WYd_PkCa1BY.jpg","w":1000,"h":667,"alt":"Business newspaper pages with headlines, photos and columns of text","cap":"Newspaper pages with headlines, photographs and text. Newspapers are built on a column grid, which keeps many stories and images aligned and makes a busy page easy to scan.","by":"AbsolutVision","title":"Real world:"},{"screen":"Print versus screen: bleed, margins and safe areas","src":"img/notes/n_Tzm3Oyu_6sk.jpg","w":1000,"h":668,"alt":"A large industrial printing machine running printed sheets","cap":"A printing press at work. Printed sheets are trimmed after printing, so designs need bleed beyond the edge and safe margins inside it, while screen layouts instead plan for different display sizes.","by":"Bank Phrom","title":"Real world:"},{"screen":"Editorial and book layout","src":"img/notes/n_3mK-WrfvinU.jpg","w":1000,"h":667,"alt":"An open book showing a page spread with photographs of people","cap":"An open book showing a spread of photographs. Editorial and book layout treat the two facing pages as one unit, balancing images, text and white space across the spread.","by":"Simran Sood","title":"Real world:"},{"screen":"Visual communication: colour, typography and layout","kind":"example","title":"Colour and lettering at night","tag":"Contrast","html":"<p>Neon words and symbols glowing on a dark wall: bright hue plus dark background gives maximum contrast, so the lettering reads from across the room.</p><p>The lesson for screens: light text on a dark background (or the reverse) is readable; mid-tone on mid-tone is not.</p>","q":null,"wide":false,"pal":[["#511911",18,"dark red"],["#b02e24",12,"red"],["#c63f91",3,"pink-red"],["#ebb14a",2,"orange"],["#67bce3",1,"cyan"]],"w":750,"h":1000,"by":"Georgie Cobbs","alt":"multicolored lighted neon signs","cap":"Colour and lettering at night","src":"img/notes/c_SU35VU5de1o.jpg"},{"screen":"Visual communication: colour, typography and layout","kind":"example","title":"Value without hue","tag":"Value","html":"<p>Remove colour and you are left with value: light and dark. This black-and-white building still has strong visual interest because of its contrast and repeated lines.</p><p>A good test for any layout is to view it in greyscale. If the hierarchy still works without colour, your design is strong.</p>","q":null,"wide":false,"pal":[["#f2f2f2",37,"near white"],["#080808",34,"near black"],["#505050",11,"grey"]],"w":800,"h":1000,"by":"Joakim Nådell","alt":"The curved facade of Axel Towers in Copenhagen against a bright sky","cap":"Value without hue","src":"img/notes/c_K67sBVqLLuw.jpg"},{"screen":"Colour theory recap, and Logo Lab","kind":"example","title":"Primary colours in a pencil case","tag":"Primary","html":"<p>Red (<span class=\"hexchip\" style=\"--c:#D84C42\"><i></i>#D84C42</span>), yellow (<span class=\"hexchip\" style=\"--c:#CA8F27\"><i></i>#CA8F27</span>) and blue (<span class=\"hexchip\" style=\"--c:#183C64\"><i></i>#183C64</span>) crayons are the RYB primaries; the green crayon is a secondary colour (blue plus yellow). Real colours are never perfectly pure: compare the crayon swatches with the colour wheel.</p>","q":null,"wide":false,"pal":[["#183c64",2,"dark blue"],["#ca8f27",2,"orange"],["#337e6e",1,"teal"],["#d84c42",1,"red"]],"w":1000,"h":668,"by":"Aisling Tempany","alt":"Four colorful crayons arranged in a cross on white","cap":"Primary colours in a pencil case","src":"img/notes/c_2BSKhC5HhRM.jpg"},{"screen":"Colour theory recap, and Logo Lab","kind":"example","title":"The Willemstad waterfront, Curaçao","tag":"Colour wheel","html":"<p>Pink, yellow-orange, teal and red-orange façades along the water: a full colour wheel in one street, with the blues of sea and sky (<span class=\"hexchip\" style=\"--c:#457CAE\"><i></i>#457CAE</span>) as the dominant background.</p>","q":null,"wide":false,"pal":[["#457cae",39,"blue"],["#2e4b70",23,"blue"],["#e9c3b0",4,"light orange"],["#752922",3,"dark red"],["#b68668",3,"orange"]],"w":1000,"h":667,"by":"Ulf Meyer","alt":"Colorful buildings line a waterfront under a blue sky","cap":"The Willemstad waterfront, Curaçao","src":"img/notes/c_CNvfGmcebgw.jpg"},{"screen":"Colour theory recap, and Logo Lab","kind":"example","title":"Complementary: a hibiscus","tag":"Complementary","html":"<p>A red hibiscus (<span class=\"hexchip\" style=\"--c:#E22C45\"><i></i>#E22C45</span>) on green leaves (<span class=\"hexchip\" style=\"--c:#59772C\"><i></i>#59772C</span>): complements make each other more intense. A logo using a red mark on a green field would be eye-catching, but test it for red-green colour blindness.</p>","q":null,"wide":false,"pal":[["#30342c",50,"charcoal"],["#e22c45",14,"red"],["#59772c",6,"yellow-green"],["#f85881",3,"pink-red"]],"w":1000,"h":667,"by":"Mufid Majnun","alt":"a red flower with green leaves in the background","cap":"Complementary: a hibiscus","src":"img/notes/c_NktB6fR8ulk.jpg"},{"screen":"How we see colour","kind":"example","title":"Splitting white light with a prism","tag":"Light","html":"<p>Sunlight looks white, but a glass prism bends each wavelength by a different amount and fans it out into a <b>spectrum</b>: red, orange, yellow, green, blue and violet. Isaac Newton's experiments with prisms showed that white light contains all these colours.</p>","q":null,"wide":false,"pal":[["#242424",55,"charcoal"],["#f1ecec",32,"near white"],["#3e4846",5,"grey"],["#c0c7c7",2,"grey"],["#62787b",2,"grey"],["#7c9298",2,"grey"]],"w":1000,"h":1000,"by":"Artem","alt":"A prism refracts light into a rainbow spectrum","cap":"Splitting white light with a prism","src":"img/notes/c_a18lCneoV4E.jpg"},{"screen":"How we see colour","kind":"example","title":"The eye: where colour begins","tag":"Biology","html":"<p>Light enters through the pupil and reaches the retina, where three types of <b>cone cell</b> respond most to long (red), medium (green) and short (blue) wavelengths. The brain combines their signals into the colours you experience.</p><p>This is why screens only need red, green and blue light to fool your eyes into seeing millions of colours.</p>","q":null,"wide":false,"pal":[["#664134",37,"orange"],["#8e5a48",20,"orange"],["#cb8d78",16,"orange"],["#3e2219",13,"dark red"],["#ecb1a4",5,"light red"],["#bf852d",1,"orange"]],"w":1000,"h":667,"by":"Joel Staveley","alt":"close-up photo of human eye","cap":"The eye: where colour begins","src":"img/notes/c_Uo87K3AkF-4.jpg"},{"screen":"How we see colour","kind":"example","title":"Why chillies look red","tag":"Reflection","html":"<p>The skin of a chilli absorbs most wavelengths of light and reflects mainly the long, red ones. Your cones detect that reflected light, so you see red. Colour is not \"in\" the pepper: it is created by light, the surface and your eye working together.</p>","q":null,"wide":false,"pal":[["#81100b",18,"dark red"],["#bc2018",8,"red"],["#9f8f79",17,"muted orange"]],"w":750,"h":1000,"by":"Jonathan Borba","alt":"Plates of red chili peppers displayed at a market","cap":"Why chillies look red","src":"img/notes/c_M7swW5Iy8cs.jpg"},{"screen":"RYB, RGB and CMYK: three ways to mix colour","kind":"example","title":"RYB: mixing paint by hand","tag":"RYB","html":"<p>Paints are <b>subtractive</b>: every pigment you add absorbs more light. Mix all the paints together and you get a muddy brown, not white. Adding white paint makes tints like the pastels in this palette.</p>","q":null,"wide":false,"pal":[["#ece8dd",24,"light muted yellow-orange"],["#603115",23,"dark orange"],["#8d4d27",20,"orange"],["#a67853",11,"orange"],["#be9d76",4,"orange"],["#d29137",2,"orange"]],"w":1000,"h":667,"by":"Jonathan Borba","alt":"Hands mixing colorful paints on a palette","cap":"RYB: mixing paint by hand","src":"img/notes/c_8iS2kIjWm4g.jpg"},{"screen":"RYB, RGB and CMYK: three ways to mix colour","kind":"example","title":"RGB: a screen up close","tag":"RGB","html":"<p>Under a macro lens a screen is just red, green and blue sub-pixels. Light is <b>additive</b>: red plus green light gives yellow, and all three at full brightness give white. Every hex code, such as <span class=\"hexchip\" style=\"--c:#86D64D\"><i></i>#86D64D</span>, describes how bright each of the three sub-pixels should glow.</p>","q":null,"wide":true,"pal":[["#360d0e",9,"dark red"],["#96341f",6,"red"],["#155eab",4,"blue"],["#86d64d",4,"green"]],"w":1000,"h":665,"by":"Gyula Jónás","alt":"Visible rgb pixels on a digital screen surface","cap":"RGB: a screen up close","src":"img/notes/c_dzjfnSneOxU.jpg"},{"screen":"RYB, RGB and CMYK: three ways to mix colour","kind":"example","title":"CMYK: the four printing inks","tag":"CMYK","html":"<p>Cyan, magenta, yellow and black inks are used in every inkjet printer and commercial press. Overlapping dots of ink create the full range of printed colours. Design for print in CMYK, and expect very bright RGB greens and blues to look duller on paper.</p>","q":null,"wide":false,"pal":[["#0a97d0",3,"cyan"],["#fa4e92",1,"pink-red"],["#f4d23e",4,"yellow-orange"],["#231a1d",5,"near black"]],"w":1000,"h":667,"by":"A J.","alt":"a row of different colored bottles sitting next to each other","cap":"CMYK: the four printing inks","src":"img/notes/c_eVhc4EojmlY.jpg"},{"screen":"Split-complementary, tetradic and square harmonies","kind":"example","title":"Split-complementary: teal and a range of oranges","tag":"Split-complementary","html":"<p>Teal sky (<span class=\"hexchip\" style=\"--c:#296272\"><i></i>#296272</span>) with yellow-orange (<span class=\"hexchip\" style=\"--c:#DDA773\"><i></i>#DDA773</span>) and red-orange (<span class=\"hexchip\" style=\"--c:#C56D2D\"><i></i>#C56D2D</span>) walls: the key colour plus the two neighbours of its complement. Strong, but less harsh than pure blue and orange.</p>","q":null,"wide":false,"pal":[["#296272",45,"cyan"],["#d98d4e",22,"orange"],["#dda773",8,"orange"],["#c56d2d",7,"orange"]],"w":667,"h":1000,"by":"Bikash Guragai","alt":"A modern orange building with angled yellow window frames against a clear blue sky","cap":"Split-complementary: teal and a range of oranges","src":"img/notes/c_K-2O9kvRnrg.jpg"},{"screen":"Split-complementary, tetradic and square harmonies","kind":"example","title":"Tetradic: Oranjestad, Aruba","tag":"Tetradic","html":"<p>Blue, yellow, pink and green buildings and trees make two complementary pairs: blue with yellow-orange, pink with green. The sky blue dominates, which keeps four strong colours under control.</p>","q":null,"wide":true,"pal":[["#abcff3",28,"light blue"],["#a79110",6,"yellow-orange"],["#3172a1",3,"blue"],["#a8566c",1,"pink-red"]],"w":1000,"h":704,"by":"Jamie Tudor","alt":"a row of brightly colored houses on a street","cap":"Tetradic: Oranjestad, Aruba","src":"img/notes/c_EUxtOZX3chs.jpg"},{"screen":"Split-complementary, tetradic and square harmonies","kind":"example","title":"Close to square: a street in Havana, Cuba","tag":"Square","html":"<p>Yellow, teal, orange and blue walls spaced around the wheel come close to a <b>square</b> scheme. Because sun and age have softened them into tints and tones, the four colours sit together comfortably.</p>","q":null,"wide":false,"pal":[["#8c7a5a",27,"muted orange"],["#aa9e81",11,"muted yellow-orange"],["#bd8b46",9,"orange"],["#2254a9",3,"blue"],["#4ea082",1,"teal"]],"w":1000,"h":667,"by":"Alex G","alt":"Old, colorful buildings flank a street with vintage cars","cap":"Close to square: a street in Havana, Cuba","src":"img/notes/c_H144zvyJ4eo.jpg"},{"screen":"Colour gradients and gradient types","kind":"example","title":"A linear gradient in the sky","tag":"Linear","html":"<p>Blue at the top, pink in the middle, orange at the horizon: a <b>linear</b> gradient running from top to bottom. Recreate it with three colour stops: <span class=\"hexchip\" style=\"--c:#729AAE\"><i></i>#729AAE</span>, <span class=\"hexchip\" style=\"--c:#D7A294\"><i></i>#D7A294</span> and <span class=\"hexchip\" style=\"--c:#FE9427\"><i></i>#FE9427</span>.</p>","q":null,"wide":false,"pal":[["#729aae",32,"muted blue"],["#3e90ab",11,"cyan"],["#d7a294",17,"red"],["#fda059",16,"orange"],["#fe9427",5,"orange"]],"w":667,"h":1000,"by":"Dave Hoefler","alt":"A smooth gradient shifting from soft blue to warm orange","cap":"A linear gradient in the sky","src":"img/notes/c_PEkfSAxeplg.jpg"},{"screen":"Colour gradients and gradient types","kind":"example","title":"A natural gradient: Bimini, Bahamas","tag":"Natural gradient","html":"<p>Water deepens from bright turquoise to deep teal (<span class=\"hexchip\" style=\"--c:#057566\"><i></i>#057566</span>). This is the inspiration behind countless Caribbean resort websites and app backgrounds.</p>","q":null,"wide":true,"pal":[["#05c9c4",18,"teal"],["#3eafb9",8,"teal"],["#0981a4",21,"cyan"],["#057566",10,"dark teal"]],"w":1000,"h":562,"by":"Ricky Beron","alt":"An aerial view of the ocean with boats in the water","cap":"A natural gradient: Bimini, Bahamas","src":"img/notes/c_pB1iUlAOkV8.jpg"},{"screen":"Colour gradients and gradient types","kind":"example","title":"A radial glow: sunset over Aruba","tag":"Radial","html":"<p>The sky is brightest around the sun and darkens outwards from it in every direction: a natural <b>radial</b> gradient from yellow-orange (<span class=\"hexchip\" style=\"--c:#FEC84C\"><i></i>#FEC84C</span>) to deeper orange (<span class=\"hexchip\" style=\"--c:#C98434\"><i></i>#C98434</span>). Radial gradients are used to suggest a light source or spotlight.</p>","q":null,"wide":false,"pal":[["#fec84c",23,"yellow-orange"],["#e9a03c",13,"orange"],["#c98434",6,"orange"],["#1a3535",52,"dark teal"]],"w":1000,"h":667,"by":"Lex Melony","alt":"sun setting over the ocean","cap":"A radial glow: sunset over Aruba","src":"img/notes/c__idYbIGUoJk.jpg"},{"screen":"The 60-30-10 rule and colour-blind-safe palettes","kind":"example","title":"60-30-10 in a real room","tag":"60-30-10","html":"<p>About 60% warm grey and beige, about 30% white curtains and walls, and a 10% accent of burnt-orange cushions (<span class=\"hexchip\" style=\"--c:#8F3805\"><i></i>#8F3805</span>, <span class=\"hexchip\" style=\"--c:#AF5C2B\"><i></i>#AF5C2B</span>). The accent is small, so it draws the eye without overwhelming the room.</p>","q":null,"wide":true,"pal":[["#a49b93",36,"grey"],["#e3e7eb",25,"light muted blue"],["#8f3805",3,"dark orange"],["#af5c2b",2,"orange"]],"w":592,"h":1000,"by":"Jetts Thanatip","alt":"A couch with orange pillows sits by a window","cap":"60-30-10 in a real room","src":"img/notes/c_jvv2e1NJc9s.jpg"},{"screen":"The 60-30-10 rule and colour-blind-safe palettes","kind":"example","title":"A red-green warning","tag":"Colour-blind safe","html":"<p>Most viewers see a vivid red flower on green leaves. Someone with deuteranopia or protanopia (red-green colour blindness) may see a much weaker difference between <span class=\"hexchip\" style=\"--c:#E22C45\"><i></i>#E22C45</span> and <span class=\"hexchip\" style=\"--c:#59772C\"><i></i>#59772C</span>. In a chart or interface, add labels, icons or patterns, not just red and green.</p>","q":null,"wide":false,"pal":[["#30342c",50,"charcoal"],["#e22c45",14,"red"],["#59772c",6,"yellow-green"],["#f85881",3,"pink-red"]],"w":1000,"h":667,"by":"Mufid Majnun","alt":"a red flower with green leaves in the background","cap":"A red-green warning","src":"img/notes/c_NktB6fR8ulk.jpg"},{"screen":"The 60-30-10 rule and colour-blind-safe palettes","kind":"example","title":"Low contrast is hard for everyone","tag":"Accessibility","html":"<p>Fog reduces the difference between light and dark. Text in colours like <span class=\"hexchip\" style=\"--c:#9394A0\"><i></i>#9394A0</span> on <span class=\"hexchip\" style=\"--c:#B8BCCD\"><i></i>#B8BCCD</span> would be very hard to read for anyone, especially people with low vision. Check text contrast against WCAG before you publish.</p>","q":null,"wide":false,"pal":[["#9394a0",27,"grey"],["#b8bccd",22,"light muted blue"],["#2b384a",14,"dark muted blue"],["#d6d4d9",7,"off-white"]],"w":1000,"h":668,"by":"Steve Adams","alt":"a foggy lake with a boat in the foreground","cap":"Low contrast is hard for everyone","src":"img/notes/c_EJbNJpCfpvo.jpg"}],"M3U7":[{"screen":"Photography basics: exposure, focus and colour balance","src":"img/notes/n_o08u5jVuy00.jpg","w":1000,"h":667,"alt":"A black camera lens resting on a brown wooden table","cap":"A camera lens on a table. The lens controls focus and, through its aperture, how much light reaches the sensor, which together with shutter speed and ISO sets the exposure of every photograph.","by":"Jason Leung","title":"Real world:"},{"screen":"Digital image essentials: pixels, resolution, DPI and bit depth","src":"img/notes/n_AkYGy_ymFqo.jpg","w":1000,"h":644,"alt":"Extreme macro view of a screen showing tiny coloured red, green and blue sub-pixels","cap":"An extreme close-up of a screen, revealing its tiny coloured elements. Every digital image is a grid of pixels like these; more pixels mean higher resolution, and bit depth sets how many colours each pixel can show.","by":"Michael Maasen","title":"Real world:"},{"screen":"Image manipulation techniques","src":"img/notes/n_PevdsGAUrKA.jpg","w":1000,"h":667,"alt":"Photo editing software open on a laptop screen","cap":"Photo editing software open on a laptop. Programs like this allow cropping, cloning, colour adjustment, layering and masking, the core techniques used to manipulate and improve a digital image.","by":"Zulfugar Karimov","title":"Real world:"},{"screen":"One-light photography","src":"img/notes/n_O_VKrby6YIU.jpg","w":1000,"h":667,"alt":"Black and white portrait of a boy lit by a single lamp in a dark room","cap":"A black and white portrait made with just one lamp in a dark room. It shows that a single, well-placed light can model a face with clear highlights and shadows, without any studio kit.","by":"Joy","title":"Real world:"},{"screen":"Rembrandt lighting","src":"img/notes/n_4lBAqUmKMt0.jpg","w":957,"h":1000,"alt":"Black and white portrait of an elderly woman with light falling from one side","cap":"A black and white portrait made with Rembrandt lighting. The light comes from one side and slightly above, leaving the far cheek in shadow apart from a small triangle of light below the eye.","by":"Mónica Solís","title":"Real world:"},{"screen":"Butterfly (Paramount) lighting","src":"img/notes/n_0fN7Fxv1eWA.jpg","w":1000,"h":780,"alt":"Black and white portrait of a woman wearing a necklace against a dark background","cap":"A black and white studio-style portrait. In butterfly lighting the main light sits high and directly in front of the face, casting a small butterfly-shaped shadow under the nose; compare where the shadows fall here.","by":"Rachel McDermott","title":"Real world:"},{"screen":"Split lighting","src":"img/notes/n_wPbbShdlEWI.jpg","w":667,"h":1000,"alt":"A face lit on one half only, with the other half disappearing into darkness","cap":"A face lit on one side only while the other half falls into darkness. This is split lighting: the light is placed at 90 degrees to the subject, creating strong drama and mystery.","by":"Stormseeker","title":"Real world:"},{"screen":"Loop lighting","src":"img/notes/n_3TLl_97HNJo.jpg","w":800,"h":1000,"alt":"Close portrait of a woman in a black top with soft light on her face","cap":"A close portrait with soft light on the face. In loop lighting the light is set a little to one side and above, so the nose casts a small loop-shaped shadow towards the cheek: a flattering everyday setup.","by":"Aiony Haust","title":"Real world:"},{"screen":"Backlighting","src":"img/notes/n_K2u71wv2eI4.jpg","w":1000,"h":667,"alt":"Silhouette of a man facing a bright sunset sky","cap":"A man silhouetted against a sunset. With the light source behind the subject, the outline glows or turns into a silhouette; this is backlighting, used for rim light, mood and separation from the background.","by":"Tim Marshall","title":"Real world:"},{"screen":"Feathering the light","src":"img/notes/n_T4bFs7q9E94.jpg","w":1000,"h":667,"alt":"Woman in a black and white shirt lit by soft light from a window","cap":"A woman lit by soft window light. Turning a light so the subject sits in the softer edge of the beam, rather than its harsh centre, is called feathering, and it gives the same gentle fall-off seen here.","by":"Andrey Zvyagintsev","title":"Real world:"},{"screen":"Audio recording: microphones, acoustics, levels and noise","src":"img/notes/n_g1P71yu7-Ss.jpg","w":1000,"h":563,"alt":"A shotgun microphone in a furry windshield mounted on a pistol grip","cap":"A shotgun microphone in a furry windshield on a pistol grip. It is highly directional, picking up the speaker it is pointed at, while the windshield cuts wind noise outdoors.","by":"Christopher Watts","title":"Real world:"},{"screen":"Video production: settings, framing and editing","src":"img/notes/n_RiiLZP8Vmj8.jpg","w":1000,"h":667,"alt":"A video camera rig mounted on a tripod","cap":"A video camera rig mounted on a tripod. Before recording, settings such as resolution, frame rate, shutter speed and white balance are chosen, and the tripod keeps framing steady for a clean edit later.","by":"Amjith S","title":"Real world:"},{"screen":"Post-production workflow and file management","src":"img/notes/n_VYfxkePredI.jpg","w":1000,"h":667,"alt":"Close-up of a silver and black hard disk drive","cap":"A hard disk drive. Good post-production starts with file management: footage is copied to drives like this, organised into clearly named folders and backed up in more than one place before editing begins.","by":"Nick","title":"Real world:"},{"screen":"Transitions and editing logic","src":"img/notes/n_PzkeY0i98io.jpg","w":1000,"h":667,"alt":"A video editing timeline with blue and purple clips on a dark background","cap":"Clips laid out on an editing timeline. The points where one clip meets the next are where cuts, dissolves and other transitions go, and each should follow the logic of the story rather than being added for show.","by":"Skye Studios","title":"Real world:"},{"screen":"Retouching, compositing and grading with integrity","src":"img/notes/n_g704cq4BMC0.jpg","w":1000,"h":667,"alt":"Photographer's workstation with film negatives on a light table beside editing software","cap":"A photographer's desk with film negatives on a light table next to editing software. Whether on film or screen, retouching and grading should improve an image honestly, without misleading viewers about what was really there.","by":"Jakub Żerdzicki","title":"Real world:"}],"M3U8":[{"screen":"Compression and the essential file formats","src":"img/notes/n_C-o9HNzQ_rA.jpg","w":1000,"h":667,"alt":"Overhead view of a person packing clothes into a suitcase","cap":"A person packing a suitcase. Compression works in a similar way: data is packed tighter to save space, either losslessly, like neat folding, or lossily, by leaving some items behind, as JPEG and MP3 do.","by":"Surface","title":"Real world:"},{"screen":"Export settings for platforms and devices","src":"img/notes/n_2mc2B5iX6as.jpg","w":1000,"h":664,"alt":"A laptop, tablet and smartphone side by side on a desk","cap":"A laptop, tablet and smartphone side by side. Each screen has a different size and shape, so work is exported with settings such as resolution, aspect ratio and file size to suit the platform and device.","by":"Firmbee.com","title":"Real world:"},{"screen":"Effective presentations with audio, video and visual aids","src":"img/notes/n_1-aA2Fadydc.jpg","w":1000,"h":667,"alt":"A group of people seated in a room facing a presenter and a projector screen","cap":"An audience watching a presentation on a projector screen. Clear visual aids, short video clips and good audio support what the speaker says, keeping the audience focused on the key message.","by":"Quilia","title":"Real world:"},{"screen":"The digital proposal portfolio","src":"img/notes/n_qqd8APhaOg4.jpg","w":1000,"h":667,"alt":"Several printed portrait photographs laid out on a white cloth","cap":"A selection of printed portraits laid out for review. A portfolio is a curated collection like this; a digital proposal portfolio gathers your best work, process evidence and plans to show what you can deliver.","by":"sarandy westfall","title":"Real world:"}]};
/* Notes photographs and real-world colour examples.
   Every notes screen gets a captioned real photograph; colour theory and colour psychology screens also get
   in-depth "Real-world example" panels: a real photo, the palette measured from it (hex codes and share of the image)
   and an analysis linked to the notes. Images are stored inside the course. Kester Small. */
(function () {
  'use strict';
  const P = window.COURSE_NOTE_PHOTOS || {};
  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  function css() {
    if (document.getElementById('nph-css')) return;
    const s = document.createElement('style'); s.id = 'nph-css';
    s.textContent = `
.nph{clear:both;margin:16px 0 18px;padding:9px;border-radius:16px;background:var(--raise,rgba(255,255,255,.05));border:1px solid var(--line,rgba(245,197,66,.3));box-shadow:0 10px 26px -12px rgba(0,0,0,.45);max-width:none}
.nph-ph{position:relative;display:block;width:100%;margin:0;padding:0;border:0;font:inherit;background:var(--surface,#0b1736);border-radius:11px;overflow:hidden;cursor:zoom-in}
.nph-ph img{display:block;width:100%;height:auto;aspect-ratio:var(--ar,3/2);object-fit:cover;max-height:min(480px,64vh)}
.nph-card .nph-ph img{max-height:340px}
.nph figcaption{margin-top:8px;font-size:.9rem;line-height:1.5}
.nph figcaption b{color:var(--gold,#F5C542)}
.nph .cr{display:block;margin-top:3px;font-size:.74rem;opacity:.75}
.nph-pal{display:flex;gap:4px;margin-top:8px;flex-wrap:wrap}
.nph-pal .sw{flex:1 1 60px;min-width:56px;border-radius:8px;overflow:hidden;border:1px solid var(--line,rgba(255,255,255,.2));background:var(--surface,#0b1736)}
.nph-pal .sw i{display:block;height:34px}
.nph-pal .sw span{display:block;padding:3px 5px;font:700 .7rem/1.25 ui-monospace,Menlo,Consolas,monospace;letter-spacing:.02em}
.nph-pal .sw small{display:block;font-weight:400;opacity:.75;font-family:var(--f-body,inherit)}
.nph-bar{display:flex;height:12px;border-radius:99px;overflow:hidden;margin-top:6px;border:1px solid var(--line,rgba(255,255,255,.2))}
.nph-bar i{display:block;height:100%}
.nph-ex{clear:both;margin:22px 0 10px;display:flex;flex-direction:column;gap:14px}
.nph-ex>h3{display:flex;align-items:center;gap:8px;font-size:1.2rem}
.nph-ex>h3::before{content:'';width:22px;height:22px;border-radius:50%;flex:none;background:conic-gradient(#E53935,#FDD835,#43A047,#1E88E5,#8E24AA,#E53935)}
.nph-ex>.lead{opacity:.9}
.nph-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}
.nph-card{display:flex;flex-direction:column;gap:9px;padding:10px;border-radius:16px;background:var(--raise,rgba(255,255,255,.05));border:1px solid var(--line,rgba(245,197,66,.3));box-shadow:0 10px 26px -12px rgba(0,0,0,.45);min-width:0}
.nph-card.wide{grid-column:1/-1}
.nph-card.wide .in{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:14px;align-items:start}
@media (max-width:700px){.nph-card.wide .in{grid-template-columns:minmax(0,1fr)}}
.nph-card .tag{align-self:flex-start;font-size:.7rem;font-weight:700;letter-spacing:.09em;text-transform:uppercase;padding:3px 10px;border-radius:99px;background:var(--soft-gold,rgba(255,215,102,.16))}
.nph-card h4{font-size:1.05rem}
.nph-card .an{display:flex;flex-direction:column;gap:7px;font-size:.93rem;line-height:1.55}
.nph-card .an p{margin:0}
.nph-card .an ul{margin:0}
.nph-card .q{margin-top:2px;padding:8px 11px;border-radius:10px;background:var(--soft-blue,rgba(245,197,66,.14));font-weight:400;font-size:.9rem}
.nph-card .q b{font-weight:700}
.nph-full{position:fixed;inset:0;z-index:80;background:rgba(3,6,18,.9);display:grid;place-items:center;padding:16px}
.nph-full figure{margin:0;max-width:min(1100px,100%);max-height:100%;display:flex;flex-direction:column;gap:8px;color:#fff}
.nph-full img{max-width:100%;max-height:calc(100vh - 140px);object-fit:contain;border-radius:10px;margin:0 auto}
.nph-full figcaption{font-size:.92rem;text-align:center}
.nph-full button{align-self:center}
.html-body.ufig-host .nph,.html-body.ufig-host .nph-ex{clear:both}
.hexchip{display:inline-flex;align-items:center;gap:4px;padding:0 6px 0 3px;border-radius:6px;background:var(--surface,rgba(0,0,0,.2));border:1px solid var(--line,rgba(255,255,255,.2));font:700 .78em/1.6 ui-monospace,Menlo,Consolas,monospace;white-space:nowrap;vertical-align:baseline}
.hexchip i{width:.95em;height:.95em;border-radius:3px;background:var(--c);border:1px solid rgba(127,127,127,.5)}`;
    document.head.appendChild(s);
  }
  function pal(p, bar) {
    if (!p || !p.length) return '';
    const sw = p.map(c => `<div class="sw" title="${esc(c[0])}"><i style="background:${esc(c[0])}"></i><span>${esc(c[0].toUpperCase())}${c[2] ? `<small>${esc(c[2])}</small>` : ''}<small>${c[1]}% of photo</small></span></div>`).join('');
    const tot = p.reduce((a, c) => a + (+c[1] || 0), 0) || 1;
    const b = bar ? `<div class="nph-bar" aria-hidden="true">${p.map(c => `<i style="background:${esc(c[0])};width:${(100 * c[1] / tot).toFixed(1)}%"></i>`).join('')}</div>` : '';
    return `<div class="nph-pal" role="list" aria-label="Colour palette measured from the photo">${sw}</div>${b}`;
  }
  function img(f, k) {
    return `<button type="button" class="nph-ph" data-nphz="${k}" aria-label="Enlarge photo" style="--ar:${f.w}/${f.h}"><img src="${esc(f.src)}" alt="${esc(f.alt)}" width="${f.w}" height="${f.h}" loading="lazy" decoding="async"></button>`;
  }
  function photo(f, k) {
    return `<figure class="nph" data-nph="${k}">${img(f, k)}${f.pal ? pal(f.pal) : ''}<figcaption><b>${esc(f.title || 'Photo')}</b> ${esc(f.cap)}<span class="cr">Photo: ${esc(f.by)}</span></figcaption></figure>`;
  }
  function card(f, k) {
    const body = `<div class="an">${f.html || ''}</div>${f.q ? `<div class="q"><b>Try it:</b> ${f.q}</div>` : ''}<span class="cr" style="font-size:.74rem;opacity:.75">Photo: ${esc(f.by)}</span>`;
    const pic = `${img(f, k)}${pal(f.pal, true)}`;
    return `<article class="nph-card${f.wide ? ' wide' : ''}">${f.tag ? `<span class="tag">${esc(f.tag)}</span>` : ''}<h4>${esc(f.title || '')}</h4>${f.wide ? `<div class="in"><div>${pic}</div><div>${body}</div></div>` : pic + body}</article>`;
  }
  function cur() {
    try {
      const A = window.COURSE_API, L = (A && A.S && A.S.loc) || {};
      let v = L.v, m = L.m, u = L.u, s = L.s;
      if (!v) { const p = new URLSearchParams(String(location.hash || '').replace(/^#/, '')); v = p.get('v'); m = p.get('m'); u = p.get('u'); s = p.get('s'); }
      if (v !== 'screen') return null;
      const M = (window.COURSE_MODULES || []).find(x => x.id === m); if (!M) return null;
      const U = M.units[+u]; if (!U) return null; const S = U.screens[s == null ? 0 : +s]; if (!S || S.type !== 'learn') return null;
      return { U, S };
    } catch (e) { return null; }
  }
  let curList = [];
  function inject() {
    const c = cur(); if (!c) return;
    const body = document.querySelector('#stage article.card .html-body') || document.querySelector('#stage .card .html-body');
    if (!body || body.querySelector('.nph,.nph-ex')) return;
    const all = (P[c.U.id] || []).filter(f => f.screen === c.S.title); if (!all.length) return;
    css(); curList = all;
    const ph = all.filter(f => f.kind !== 'example'), ex = all.filter(f => f.kind === 'example');
    if (ph.length) {
      const html = ph.map(f => photo(f, all.indexOf(f))).join('');
      const kids = [...body.children].filter(e => !e.classList.contains('ufig'));
      const firstP = kids.find(e => e.tagName === 'P' && (e.textContent || '').trim().length > 40);
      if (firstP) firstP.insertAdjacentHTML('afterend', html); else body.insertAdjacentHTML('afterbegin', html);
    }
    if (ex.length) {
      const intro = ex[0].intro || 'Each photo below is a real scene. The swatches show the main colours measured from the photo, with their hex codes and how much of the image each one covers.';
      const html = `<section class="nph-ex" aria-label="Real-world colour examples"><h3>Real-world examples</h3><p class="lead">${intro}</p><div class="nph-grid">${ex.map(f => card(f, all.indexOf(f))).join('')}</div></section>`;
      const tip = [...body.children].reverse().find(e => e.classList && e.classList.contains('tip'));
      const fig = body.querySelector('.nfig');
      if (fig) fig.insertAdjacentHTML('beforebegin', html); else if (tip) tip.insertAdjacentHTML('beforebegin', html); else body.insertAdjacentHTML('beforeend', html);
    }
  }
  document.addEventListener('click', e => {
    const z = e.target.closest && e.target.closest('[data-nphz]'); if (!z) return;
    const f = curList[+z.dataset.nphz]; if (!f) return;
    const ov = document.createElement('div'); ov.className = 'nph-full'; ov.setAttribute('role', 'dialog'); ov.setAttribute('aria-label', f.title || 'Photo');
    ov.innerHTML = `<figure><img src="${esc(f.src)}" alt="${esc(f.alt)}"><figcaption><b>${esc(f.title || '')}</b> ${esc(f.cap || '')}</figcaption><button type="button" class="btn gold">Close</button></figure>`;
    ov.addEventListener('click', ev => { if (ev.target === ov || ev.target.closest('button')) ov.remove(); });
    document.addEventListener('keydown', function k(ev) { if (ev.key === 'Escape') { ov.remove(); document.removeEventListener('keydown', k); } });
    document.body.appendChild(ov); const b = ov.querySelector('button'); if (b) b.focus();
  });
  let q = 0; const kick = () => { if (q) return; q = requestAnimationFrame(() => { q = 0; try { inject(); } catch (e) { } }); };
  window.addEventListener('hashchange', kick); window.addEventListener('popstate', kick);
  const start = () => { const st = document.getElementById('stage'); if (st) new MutationObserver(kick).observe(st, { childList: true, subtree: true }); kick(); };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else setTimeout(start, 0);
})();
